export default function Admin(){
 const [user,setUser]=useState(()=>{try{return JSON.parse(sessionStorage.getItem('codesazan-admin-user')||'null')}catch{return null}});
 const [login,setLogin]=useState({password:''}),[loginError,setLoginError]=useState('');
 const [tab,setTab]=useState('dashboard'),[data,setData]=useState({}),[editing,setEditing]=useState(null),[busy,setBusy]=useState(false),[mediaLoadError,setMediaLoadError]=useState('');
 const mainRef=useRef(null);
 const load=async()=>{const reqs=[getAdminDashboard(),getAdminResource('portfolio'),getAdminResource('team'),getAdminResource('services'),getAdminResource('blog'),getAdminContacts(),getAdminUsers(),getAdminMessages(),getAnalytics(),getAuditLogs(),getSubscriptions(),getAdminEnrollments(),getAdminResource('courses'),getAdminPermissions(),getAdminRoles(),getAdminPlans(),getAdminSiteSettings(),getAdminReviews(),getAdminOrders(),getAdminMedia(),getAdminLoyalty(),getAdminNotifications(),getAdminNotificationRules(),getAdminNotificationProviders(),getAdminCRM(),getCRMReport(),getAdminTickets(),getAdminTicketCategories(),getAdminContracts(),getAdminContractDashboard()];const r=await Promise.allSettled(reqs);const val=i=>r[i]?.status==='fulfilled'?r[i].value?.data:[];const mediaResult=r[19];setMediaLoadError(mediaResult?.status==='rejected'?(mediaResult.reason?.response?.data?.message||mediaResult.reason?.message||'دریافت اطلاعات Media ناموفق بود'):'');setData({dash:val(0),portfolio:val(1),team:val(2),services:val(3),blog:val(4),contacts:val(5),users:val(6),messages:val(7),analytics:val(8),audit:val(9),subscriptions:val(10),enrollments:val(11),courses:val(12),permissions:val(13),roles:val(14),plans:val(15),siteSettings:val(16),reviews:val(17),orders:val(18),media:val(19),loyalty:val(20),notifications:val(21),notificationRules:val(22),notificationProviders:val(23),crm:val(24),crmReport:val(25),tickets:val(26),ticketCategories:val(27),contracts:val(28),contractReport:val(29)})};
 useEffect(()=>{if(user?.role==='admin')load()},[user?.role]);
 useEffect(()=>{if(!mainRef.current)return;requestAnimationFrame(()=>{const y=mainRef.current.getBoundingClientRect().top+window.scrollY-82;window.scrollTo({top:Math.max(0,y),left:0,behavior:'smooth'})})},[tab]);
 if(user?.role!=='admin')return <section className="section"><div className="container"><div className="admin-login"><div className="admin-logo">⌘</div><h1>ورود مدیر</h1><p>رمز مدیریت را وارد کنید. احراز هویت پنل از حساب عمومی کاربران جداست.</p><form onSubmit={async e=>{e.preventDefault();setLoginError('');try{const r=await adminLogin(login.password);const u={id:'admin-env',username:'admin',name:'مدیر سیستم',role:'admin',permissions:['*']};sessionStorage.setItem('codesazan-admin-token',r.token);sessionStorage.setItem('codesazan-admin-user',JSON.stringify(u));setUser(u);setLogin({password:''})}catch(e){setLoginError(e.response?.data?.message||e.message||'ورود ناموفق بود')}}}><input autoFocus className="admin-input" type="password" placeholder="رمز مدیریت" value={login.password} onChange={e=>setLogin({password:e.target.value})}/>{loginError&&<div className="form-msg show err">{loginError}</div>}<button className="btn btn-primary full-btn">ورود به پنل</button></form></div></div></section>;
const labels={dashboard:'داشبورد',portfolio:'پورتفولیو',team:'تیم و رزومه',services:'خدمات',blog:'وبلاگ',courses:'دوره‌ها',media:'🎬 مدیریت ویدئو / Media',plans:'پلن‌های اشتراک',users:'کاربران',roles:'نقش‌ها و دسترسی‌ها',messages:'پیام‌های مدرس',reviews:'نظرات و ارجاع‌ها',contacts:'تماس‌ها',analytics:'آمار بازدید',audit:'Audit Log',subscriptions:'خریدهای ثبت‌شده',loyalty:'باشگاه مشتریان',communication:'✉️ مرکز پیام و ایمیل',crm:'👥 CRM مشتریان',tickets:'🎫 مرکز تیکت',contracts:'📄 قراردادهای الکترونیکی',enrollments:'خریدها و پیشرفت',siteSettings:'تنظیمات سایت',notifications:'🔔 سامانه اعلان‌ها',orders:'💳 پرداخت‌ها و درگاه‌ها'};const type=['portfolio','team','services','blog','courses'].includes(tab)?tab:null;
const save=async(item,t)=>{setBusy(true);try{await saveAdminResource(t,item);setEditing(null);await load()}catch(e){alert(e?.response?.data?.message||e?.message||'ذخیره انجام نشد')}finally{setBusy(false)}};const saveRole=async(v)=>{setBusy(true);try{const r=v.__existing?await updateAdminRole(v.key,{title:v.title,permissions:v.permissions||[]}):await createAdminRole({key:v.key,title:v.title,permissions:v.permissions||[]});if(!r?.data?.success&&r?.data?.success!==undefined)throw new Error(r.data.message||'ذخیره نقش انجام نشد');setEditing(null);await load()}catch(e){alert(e?.response?.data?.message||e?.message||'ذخیره نقش انجام نشد')}finally{setBusy(false)}};const remove=async(id,t)=>{if(confirm('این مورد حذف شود؟')){await deleteAdminResource(t,id);await load()}};
return <section className="admin-shell"><div className="container admin-layout"><aside className="admin-sidebar"><div className="admin-brand">⌘ <span>Control Room</span></div>{Object.entries(labels).filter(([k])=>!['notificationPaymentHub'].includes(k)).map(([k,v])=><button key={k} className={`${tab===k?'active ':''}${k==='media'?'media-nav':''}`} onClick={()=>{setTab(k);}}>{v}{k==='media'&&<span className="nav-badge">{(data.media?.jobs||[]).length}</span>}</button>)}</aside><main ref={mainRef} className="admin-main"><div className="admin-head"><div><span className="eyebrow">اتاق مدیریت · نسخه 6.1.5.0</span><h1>{labels[tab]}</h1></div><div className="admin-status"><i/> مدیر <button type="button" className="btn btn-outline" style={{marginRight:12}} onClick={()=>{sessionStorage.removeItem('codesazan-admin-token');sessionStorage.removeItem('codesazan-admin-user');setUser(null)}}>خروج</button></div></div>{tab==='dashboard'&&<Dashboard d={data.dash} onOpen={setTab} mediaCount={(data.media?.jobs||[]).length} communicationCount={(data.messages||[]).length+(data.contacts||[]).length}/>} {tab==='siteSettings'&&<SiteSettingsPanel value={data.siteSettings} onSave={async v=>{setBusy(true);try{const r=await updateAdminSiteSettings(v);setData(d=>({...d,siteSettings:r.data}))}finally{setBusy(false)}}} busy={busy}/>} {type&&<Resource tab={tab} items={data[tab]||[]} onAdd={()=>setEditing({...empty[tab],...(tab==='services'?{__service:true}:{}),...(tab==='blog'?{__blog:true}:{})})} onEdit={x=>setEditing({...x,...(tab==='services'?{__service:true}:{}),...(tab==='blog'?{__blog:true}:{})})} onDelete={id=>remove(id,tab)}/>} {tab==='plans'&&<PlansPanel items={data.plans||[]} onAdd={async()=>{const c=(data.courses||[])[0];if(c)setEditing({__plan:true,courseId:c.id,key:'',title:'',price:'رایگان',features:[],free:true,guestAllowed:true})}} onEdit={x=>setEditing({...x,__plan:true,__existing:true})} onDelete={async x=>{if(confirm('این پلن حذف شود؟')){await deleteAdminPlan(x.courseId,x.key);await load()}}}/>} {tab==='roles'&&<RolesPanel items={data.roles||[]} onAdd={()=>setEditing({__role:true,key:'',title:'',permissions:[]})} onEdit={x=>setEditing({...x,__role:true,__existing:true})} onDelete={async x=>{if(confirm('این نقش حذف شود؟')){await deleteAdminRole(x.key);await load()}}}/>} {tab==='users'&&<UsersPanel items={data.users||[]} onAdd={()=>setEditing({__user:true,__newUser:true,name:'',username:'',email:'',phone:'',password:'',role:'user',permissions:[],status:'active',profile:{}})} onEdit={x=>setEditing({...x,__user:true,profile:{...(x.profile||{})}})}/>} {tab==='messages'&&<Messages items={data.messages||[]}/>} {tab==='reviews'&&<ReviewsPanel items={data.reviews||[]} users={data.users||[]} onSave={async(id,payload)=>{await updateAdminReview(id,payload);await load()}}/>} {tab==='contacts'&&<Messages items={data.contacts||[]} contact/>} {tab==='analytics'&&<AnalyticsPanel d={data.analytics}/>} {tab==='audit'&&<AuditPanel items={data.audit||[]}/>} {(tab==='notifications'||tab==='orders')&&<NotificationPaymentDashboard data={data} onReload={load} initial={tab}/>} {tab==='loyalty'&&<LoyaltyPanel value={data.loyalty} onReload={load}/>} {tab==='communication'&&<CommunicationCenter data={data} onSend={async payload=>{await sendAdminEmail(payload);await load()}}/>} {tab==='crm'&&<CRMPanel items={data.crm||[]} report={data.crmReport} users={data.users||[]} contracts={data.contracts||[]} contractReport={data.contractReport} onReload={load} onOpen={setTab}/>} {tab==='tickets'&&<TicketsPanel items={data.tickets||[]} categories={data.ticketCategories||[]} contacts={data.crm||[]} users={data.users||[]} onReload={load} onOpen={setTab}/>} {tab==='contracts'&&<ContractsPanel items={data.contracts||[]} report={data.contractReport} contacts={data.crm||[]} users={data.users||[]} onReload={load} onOpen={setTab}/>} {tab==='subscriptions'&&<ListPanel title="خریدهای ثبت‌شده" items={data.subscriptions||[]} getTitle={x=>x.courseId} getSub={x=>`${x.plan} · ${x.price} · ${x.status}`}/>} {tab==='enrollments'&&<EnrollmentPanel items={data.enrollments||[]}/>} {tab==='media'&&<MediaPanel value={data.media} onReload={load} loadError={mediaLoadError}/>}</main></div>{editing&&<Editor item={editing} busy={busy} close={()=>setEditing(null)} save={save} saveRole={saveRole} courses={data.courses||[]} roles={data.roles||[]} permissions={data.permissions||[]}/>}</section>}
function AdminCrmHeader({eyebrow,title,description,icon='✦',stats=[]}){return <div className="admin-crm-hero"><div className="admin-crm-hero-icon">{icon}</div><div className="admin-crm-hero-copy"><span>{eyebrow}</span><h2>{title}</h2><p>{description}</p></div><div className="admin-crm-hero-stats">{stats.map((x,i)=><div key={i}><small>{x.label}</small><b>{x.value}</b></div>)}</div></div>}

function Dashboard({d,onOpen,mediaCount,communicationCount}){return <><div className="admin-quick-tools"><button className="admin-quick-card media-quick" onClick={()=>onOpen('media')}><span className="quick-icon">🎬</span><span><b>مدیریت ویدئو</b><small>آپلود، HLS، اتصال به درس، Retry و حذف</small></span><strong>{mediaCount||0}</strong></button><button className="admin-quick-card communication-quick" onClick={()=>onOpen('communication')}><span className="quick-icon">✉️</span><span><b>مرکز پیام و ایمیل</b><small>صندوق پیام، تماس، ارسال و وضعیت ایمیل</small></span><strong>{communicationCount||0}</strong></button><button className="admin-quick-card communication-quick" onClick={()=>onOpen('crm')}><span className="quick-icon">👥</span><span><b>CRM مشتریان</b><small>مخاطبین، لیدها، Timeline و فعالیت‌ها</small></span><strong>CRM</strong></button><button className="admin-quick-card media-quick" onClick={()=>onOpen('tickets')}><span className="quick-icon">🎫</span><span><b>مرکز تیکت</b><small>تیکت، SLA، تخصیص و پاسخ داخلی</small></span><strong>Ticket</strong></button><button className="admin-quick-card notification-quick" onClick={()=>onOpen('notifications')}><span className="quick-icon">🔔</span><span><b>مرکز اعلان‌ها</b><small>صف ارسال، رویدادها، ایمیل، پیامک و اعلان‌های پنل</small></span><strong>اعلان</strong></button><button className="admin-quick-card gateway-quick" onClick={()=>onOpen('orders')}><span className="quick-icon">💳</span><span><b>درگاه‌ها و پرداخت‌ها</b><small>درگاه‌ها، تراکنش‌ها، سفارش‌ها و وضعیت پرداخت</small></span><strong>درگاه</strong></button></div><div className="admin-stat-grid">{[['پروژه‌ها',d?.portfolio],['تیم',d?.team],['دوره‌ها',d?.courses],['کاربران',d?.users],['ثبت‌نام‌ها',d?.enrollments],['پیام‌ها',d?.messages]].map(x=><div className="admin-stat" key={x[0]}><span>{x[0]}</span><b>{x[1]??0}</b><small>وضعیت فعلی</small></div>)}</div><div className="admin-panel"><h2>آخرین درخواست‌ها</h2>{(d?.recentContacts||[]).map(x=><div className="contact-row" key={x.id}><b>{x.name}</b><span>{x.subject}</span></div>)}</div></>}
function Resource({tab,items,onAdd,onEdit,onDelete}){const title=tab==='portfolio'?'نمونه‌کارها':tab==='team'?'اعضای تیم و رزومه':tab==='services'?'خدمات':tab==='blog'?'مقالات وبلاگ':'دوره‌ها و جلسات';return <div className="admin-crm-page"><AdminCrmHeader eyebrow="مدیریت محتوا" title={title} description="مدیریت این بخش در یک فضای یکپارچه، خوانا و چندپنله انجام می‌شود." icon="✦" stats={[{label:'تعداد موارد',value:items.length.toLocaleString('fa-IR')}]} /><section className="admin-crm-surface"><div className="panel-title"><div><h2>{title}</h2><p className="muted">فهرست، ویرایش و مدیریت موارد این بخش</p></div><button className="btn btn-primary" onClick={onAdd}>+ افزودن مورد جدید</button></div><div className="admin-list">{items.map(x=><div className="admin-list-row" key={x.id}>{x.photo?<img className="mini-avatar" src={x.photo} alt=""/>:<div className="mini-avatar">{(x.title||x.name||'').slice(0,2)}</div>}<div className="row-main"><b>{x.title||x.name}</b><span>{x.client||x.role||`${x.level||''} · ${(x.lessons||[]).length} جلسه`}</span></div><button className="icon-btn" title="ویرایش" onClick={()=>onEdit(x)}>{icons.edit}</button><button className="icon-btn danger" title="حذف" onClick={()=>onDelete(x.id)}>{icons.delete}</button></div>)}</div></section></div>}
function UsersPanel({items,onEdit,onAdd}){return <div className="admin-panel"><div className="panel-title"><div><h2>کاربران و وضعیت حساب</h2><p className="muted">کاربر جدید را بسازید تا بتوانید او را در CRM، قرارداد و تیکت به‌عنوان مسئول انتخاب کنید.</p></div><button className="btn btn-primary" onClick={onAdd}>+ کاربر جدید</button></div>{items.map(x=><div className="contact-row" key={x.id}><div><b>{x.name} <small className="badge">{x.role}</small></b><span>{x.username||'-'} · {x.email} · {x.phone||'-'} · {x.status==='suspended'?'تعلیق‌شده':'فعال'}</span></div><button className="icon-btn" title="ویرایش کاربر" onClick={()=>onEdit(x)}>{icons.edit}</button></div>)}</div>}
function RolesPanel({items,onAdd,onEdit,onDelete}){return <div className="admin-panel"><div className="panel-title"><h2>نقش‌ها و دسترسی‌ها</h2><button className="btn btn-primary" onClick={onAdd}>+ نقش جدید</button></div>{items.map(x=><div className="admin-list-row" key={x.key}><div className="row-main"><b>{x.title} <small>({x.key})</small></b><span>{(x.permissions||[]).join(' · ')||'بدون دسترسی'}</span></div><button className="icon-btn" title="ویرایش" onClick={()=>onEdit(x)}>{icons.edit}</button><button className="icon-btn danger" title="حذف" disabled={x.system} onClick={()=>onDelete(x)}>{icons.delete}</button></div>)}</div>}
function PlansPanel({items,onAdd,onEdit,onDelete}){return <div className="admin-panel"><div className="panel-title"><div><h2>پلن‌های اشتراک</h2><p className="muted">هر پلن به‌صورت یک باکس مستقل قابل ویرایش و حذف است.</p></div><button className="btn btn-primary" onClick={onAdd}>+ پلن جدید</button></div><div className="plan-admin-grid">{items.map(x=><div className="plan-admin-card" key={`${x.courseId}-${x.key}`}><span className="badge">{x.courseTitle}</span><h3>{x.title}</h3><strong>{x.price}</strong><p>{(x.features||[]).join(' · ')||'بدون توضیح'}</p><div className="row-actions"><button className="icon-btn" title="ویرایش" onClick={()=>onEdit(x)}>{icons.edit}</button><button className="icon-btn danger" title="حذف" onClick={()=>onDelete(x)}>{icons.delete}</button></div></div>)}</div></div>}
function NotificationPaymentDashboard({data,onReload,initial}){
 const [active,setActive]=useState(initial==='orders'?'payments':'notifications');
 const [view,setView]=useState(initial==='orders'?'overview':'overview');
 useEffect(()=>{setActive(initial==='orders'?'payments':'notifications');setView('overview')},[initial]);
 const notifications=(data.notifications?.items||[]), rules=data.notificationRules||[], providers=data.notificationProviders||[], orders=data.orders||[];
 const paymentProviders=providers.filter(x=>x.kind==='payment');
 const sent=notifications.filter(x=>x.status==='sent').length, failed=notifications.filter(x=>x.status==='failed').length, pending=notifications.filter(x=>!['sent','failed'].includes(x.status)).length;
 const paid=orders.filter(x=>x.status==='paid').length, pendingPay=orders.filter(x=>x.status==='pending_payment').length, failedPay=orders.filter(x=>x.status==='failed').length;
 const openView=(v)=>setView(v);
 return <div className="crm50 crm51 ops-secondary-dashboard" dir="rtl">
   <aside className="crm50-side">
    <div className="crm50-side-brand"><span className="crm50-logo">{active==='notifications'?'N':'₿'}</span><div><b>{active==='notifications'?'اعلان‌ها':'درگاه‌ها'}</b><small>{active==='notifications'?'مرکز مدیریت اعلان‌ها':'مرکز مدیریت پرداخت'}</small></div></div>
    <div className="crm50-side-label">فضای کاری</div>
    <button className={view==='overview'?'active':''} onClick={()=>openView('overview')}><span>▦</span>نمای کلی</button>
    {active==='notifications'?<>
      <button className={view==='outbox'?'active':''} onClick={()=>openView('outbox')}><span>◫</span>صف ارسال</button>
      <button className={view==='rules'?'active':''} onClick={()=>openView('rules')}><span>◎</span>رویدادها و کانال‌ها</button>
      <button className={view==='providers'?'active':''} onClick={()=>openView('providers')}><span>◷</span>سرویس‌دهنده‌ها</button>
    </>:<>
      <button className={view==='orders'?'active':''} onClick={()=>openView('orders')}><span>▤</span>تراکنش‌ها و سفارش‌ها</button>
      <button className={view==='gateways'?'active':''} onClick={()=>openView('gateways')}><span>◎</span>درگاه‌ها</button>
      <button className={view==='methods'?'active':''} onClick={()=>openView('methods')}><span>◷</span>روش‌های پرداخت</button>
    </>}
    <div className="crm50-side-spacer"/>
    <div className="ops-switcher">
      <button className={active==='notifications'?'active':''} onClick={()=>{setActive('notifications');setView('overview')}}>🔔 مرکز اعلان‌ها</button>
      <button className={active==='payments'?'active':''} onClick={()=>{setActive('payments');setView('overview')}}>💳 درگاه‌ها</button>
    </div>
    <div className="crm50-side-note"><b>کنترل سریع</b><span>تمام تنظیمات این بخش در همین پیشخوان و بر اساس دسترسی مدیر قابل مدیریت است.</span></div>
   </aside>
   <main className="crm50-main">
    <header className="crm50-topbar">
      <div><div className="crm50-breadcrumb">مدیریت {active==='notifications'?'اعلان‌ها':'پرداخت‌ها'} <i>/</i> {view==='overview'?'نمای کلی':view==='outbox'?'صف ارسال':view==='rules'?'رویدادها و کانال‌ها':view==='providers'?'سرویس‌دهنده‌ها':view==='orders'?'تراکنش‌ها و سفارش‌ها':view==='gateways'?'درگاه‌ها':'روش‌های پرداخت'}</div><h1>{active==='notifications'?'مرکز فرمان اعلان‌ها':'مرکز فرمان درگاه‌ها و پرداخت'}</h1></div>
      <div className="crm50-actions"><button className="crm50-secondary" onClick={()=>{setActive(active==='notifications'?'payments':'notifications');setView('overview')}}>{active==='notifications'?'رفتن به درگاه‌ها':'رفتن به اعلان‌ها'}</button></div>
    </header>
    <div className="crm50-toolbar"><div className="crm50-search"><span>⌕</span><input readOnly value={active==='notifications'?'جستجو و مدیریت رویدادها، صف ارسال و سرویس‌دهنده‌ها':'جستجو و مدیریت تراکنش‌ها، سفارش‌ها و درگاه‌ها'} /></div><button className="crm50-tool" onClick={()=>openView(active==='notifications'?'outbox':'orders')}>{active==='notifications'?'صف ارسال':'سفارش‌ها'} <b>{(active==='notifications'?notifications:orders).length.toLocaleString('fa-IR')}</b></button><button className="crm50-tool" onClick={()=>openView(active==='notifications'?'rules':'gateways')}>{active==='notifications'?'قوانین اعلان':'درگاه‌های فعال'} <b>{(active==='notifications'?rules:paymentProviders).length.toLocaleString('fa-IR')}</b></button><button className="crm50-tool" onClick={()=>openView(active==='notifications'?'providers':'methods')}>{active==='notifications'?'سرویس‌دهنده‌ها':'روش‌های پرداخت'} <b>{(active==='notifications'?providers:paymentProviders).length.toLocaleString('fa-IR')}</b></button></div>
    {view==='overview'&&<>
      <section className="crm50-kpis"><div className="crm50-kpi primary"><small>{active==='notifications'?'کل اعلان‌های صف':'کل سفارش‌ها'}</small><strong>{(active==='notifications'?notifications.length:orders.length).toLocaleString('fa-IR')}</strong><span>{active==='notifications'?'پیام‌های ثبت‌شده برای ارسال':'سفارش‌های ثبت‌شده در سیستم'}</span></div><div className="crm50-kpi"><small>{active==='notifications'?'ارسال موفق':'پرداخت موفق'}</small><strong>{(active==='notifications'?sent:paid).toLocaleString('fa-IR')}</strong><span>{active==='notifications'?'ارسال‌شده با موفقیت':'سفارش‌های پرداخت‌شده'}</span></div><div className="crm50-kpi"><small>{active==='notifications'?'در انتظار':'در انتظار پرداخت'}</small><strong>{(active==='notifications'?pending:pendingPay).toLocaleString('fa-IR')}</strong><span>موارد نیازمند پیگیری</span></div><div className="crm50-kpi"><small>{active==='notifications'?'ناموفق':'پرداخت ناموفق'}</small><strong>{(active==='notifications'?failed:failedPay).toLocaleString('fa-IR')}</strong><span>موارد دارای خطا</span></div></section>
      <section className="crm50-workgrid">
       <article className="crm50-surface crm50-pipeline"><div className="crm50-surface-head"><div><small>{active==='notifications'?'مرکز عملیات اعلان':'مرکز عملیات پرداخت'}</small><h2>{active==='notifications'?'مدیریت اعلان‌ها':'مدیریت درگاه‌ها و پرداخت'}</h2><p>{active==='notifications'?'صف ارسال، قوانین و کانال‌ها را از یک نمای عملیاتی مدیریت کنید.':'درگاه‌ها، تراکنش‌ها و سفارش‌ها را از یک نمای عملیاتی مدیریت کنید.'}</p></div></div><div className="ops-stage-grid">{(active==='notifications'?[['outbox','صف ارسال',notifications.length,'مشاهده صف'],['rules','قوانین اعلان',rules.length,'مدیریت قوانین'],['providers','سرویس‌دهنده‌ها',providers.length,'تنظیم سرویس‌دهنده']]:[['orders','تراکنش‌ها و سفارش‌ها',orders.length,'مشاهده سفارش‌ها'],['gateways','درگاه‌ها',paymentProviders.length,'مدیریت درگاه‌ها'],['methods','روش‌های پرداخت',paymentProviders.length,'تنظیم روش‌ها']]).map(x=><button key={x[0]} className="ops-stage" onClick={()=>openView(x[0])}><span>{String(x[2]).padStart(2,'0')}</span><b>{x[1]}</b><strong>{x[2].toLocaleString('fa-IR')}</strong><small>{x[3]} ←</small></button>)}</div></article>
       <article className="crm50-surface crm50-focus"><div className="crm50-surface-head"><div><small>تمرکز امروز</small><h2>صف کار</h2></div></div>{(active==='notifications'?[['outbox','موارد صف ارسال',pending],['rules','قوانین فعال',rules.filter(x=>x.enabled).length],['providers','سرویس‌دهنده‌ها',providers.length],['failed','ارسال ناموفق',failed]]:[['orders','سفارش‌های در انتظار',pendingPay],['gateways','درگاه‌های فعال',paymentProviders.filter(x=>x.active).length],['methods','روش‌های پرداخت',paymentProviders.length],['failed','پرداخت ناموفق',failedPay]]).map((x,i)=><button key={x[0]} onClick={()=>openView(['outbox','rules','providers','failed'].includes(x[0])&&active==='notifications'?x[0]:x[0])}><span>{String(i+1).padStart(2,'0')}</span><div><b>{x[1]}</b><small>{x[2].toLocaleString('fa-IR')} مورد</small></div><em>←</em></button>)}</article>
      </section>
      <section className="crm50-workgrid lower"><article className="crm50-surface"><div className="crm50-surface-head"><div><small>آخرین موارد</small><h2>{active==='notifications'?'آخرین اعلان‌ها':'آخرین سفارش‌ها'}</h2></div><button onClick={()=>openView(active==='notifications'?'outbox':'orders')}>همه موارد ←</button></div>{active==='notifications'?<NotificationsRecent items={notifications.slice(0,7)}/>:<OrdersRecent items={orders.slice(0,7)}/>}</article><article className="crm50-surface crm50-owners"><div className="crm50-surface-head"><div><small>وضعیت کلی</small><h2>{active==='notifications'?'کانال‌های اعلان':'وضعیت پرداخت'}</h2></div></div>{active==='notifications'?<><div className="ops-mini"><span>پنل</span><b>{notifications.filter(x=>x.channel==='in_app').length.toLocaleString('fa-IR')}</b></div><div className="ops-mini"><span>ایمیل</span><b>{notifications.filter(x=>x.channel==='email').length.toLocaleString('fa-IR')}</b></div><div className="ops-mini"><span>پیامک</span><b>{notifications.filter(x=>x.channel==='sms').length.toLocaleString('fa-IR')}</b></div></>:<><div className="ops-mini"><span>موفق</span><b>{paid.toLocaleString('fa-IR')}</b></div><div className="ops-mini"><span>در انتظار</span><b>{pendingPay.toLocaleString('fa-IR')}</b></div><div className="ops-mini"><span>ناموفق</span><b>{failedPay.toLocaleString('fa-IR')}</b></div></>}</article></section>
    </>}
    {view==='outbox'&&active==='notifications'&&<NotificationsPanel value={data.notifications} rules={rules} providers={providers} onReload={onReload}/>} 
    {view==='rules'&&active==='notifications'&&<NotificationsRulesOnly rules={rules} onReload={onReload}/>} 
    {view==='providers'&&active==='notifications'&&<NotificationsProvidersOnly providers={providers} onReload={onReload}/>} 
    {view==='orders'&&active==='payments'&&<OrdersPanel items={orders} providers={providers} onReload={onReload}/>} 
    {view==='gateways'&&active==='payments'&&<PaymentGatewaysOnly providers={paymentProviders} onReload={onReload}/>} 
    {view==='methods'&&active==='payments'&&<PaymentMethodsOnly providers={paymentProviders} onReload={onReload}/>} 
   </main>
  </div>
}
function NotificationsRecent({items}){return <div className="crm50-recent-list">{items.map(n=><div className="ops-recent" key={n.id}><i>🔔</i><div><b>{n.channel==='sms'?'پیامک':'ایمیل'} · {n.recipient}</b><small>{n.event_key} · {n.body||'—'}</small></div><strong>{n.status==='sent'?'ارسال‌شده':n.status==='failed'?'ناموفق':'در صف'}</strong></div>)}{!items.length&&<div className="crm50-empty">اعلانی برای نمایش وجود ندارد.</div>}</div>}
function OrdersRecent({items}){return <div className="crm50-recent-list">{items.map(x=><div className="ops-recent" key={x.id}><i>💳</i><div><b>{x.name||'کاربر'}</b><small>{x.trackingCode||x.referenceId||'—'} · {Number(x.amount||0).toLocaleString('fa-IR')} تومان</small></div><strong>{x.status==='paid'?'پرداخت‌شده':x.status==='pending_payment'?'منتظر پرداخت':x.status==='failed'?'ناموفق':x.status}</strong></div>)}{!items.length&&<div className="crm50-empty">سفارشی برای نمایش وجود ندارد.</div>}</div>}
function NotificationsRulesOnly({rules,onReload}){const [busy,setBusy]=useState(false);const save=async x=>{setBusy(true);try{await updateAdminNotificationRule(x.event_key,{enabled:x.enabled,inApp:x.in_app,email:x.email,sms:x.sms,push:x.push});await onReload()}finally{setBusy(false)}};return <section className="crm50-surface crm50-full ops-content"><div className="crm50-surface-head"><div><small>پیکربندی اعلان</small><h2>رویدادها و کانال‌ها</h2><p>برای هر رویداد مشخص کنید از چه کانال‌هایی اعلان ارسال شود.</p></div></div><div className="notification-rules">{rules.map(x=><div className="notification-rule" key={x.event_key}><div><b>{x.title}</b><span>{x.category} · {x.event_key}</span><small>{x.description}</small></div><div className="notification-channels"><label><input disabled={busy} type="checkbox" checked={x.enabled} onChange={e=>save({...x,enabled:e.target.checked})}/> فعال</label><label><input disabled={busy} type="checkbox" checked={x.in_app} onChange={e=>save({...x,in_app:e.target.checked})}/> پنل</label><label><input disabled={busy} type="checkbox" checked={x.email} onChange={e=>save({...x,email:e.target.checked})}/> ایمیل</label><label><input disabled={busy} type="checkbox" checked={x.sms} onChange={e=>save({...x,sms:e.target.checked})}/> پیامک</label></div></div>)}</div></section>}
function NotificationsProvidersOnly({providers,onReload}){const save=async x=>{await updateAdminNotificationProvider(x.provider_key,{active:x.active,config:x.config||{}});await onReload()};return <section className="crm50-surface crm50-full ops-content"><div className="crm50-surface-head"><div><small>اتصال سرویس‌ها</small><h2>سرویس‌دهنده‌های اعلان</h2><p>ایمیل، پیامک و سایر سرویس‌های اعلان را از اینجا مدیریت کنید.</p></div></div><div className="notification-providers">{providers.map(x=><ProviderEditor key={x.provider_key} item={x} busy={false} onSave={save}/>)}</div></section>}
function PaymentGatewaysOnly({providers,onReload}){const save=async x=>{await updateAdminNotificationProvider(x.provider_key,{active:x.active,config:x.config||{}});await onReload()};return <section className="crm50-surface crm50-full ops-content"><div className="crm50-surface-head"><div><small>مرکز اتصال مالی</small><h2>درگاه‌های پرداخت</h2><p>درگاه‌های فعال و تنظیمات اتصال را مدیریت کنید.</p></div></div><div className="notification-providers">{providers.map(x=><ProviderEditor key={x.provider_key} item={x} busy={false} onSave={save}/>)}</div>{!providers.length&&<div className="empty-state">درگاهی ثبت نشده است.</div>}</section>}
function PaymentMethodsOnly({providers,onReload}){return <section className="crm50-surface crm50-full ops-content"><div className="crm50-surface-head"><div><small>تنظیمات پرداخت</small><h2>روش‌های پرداخت</h2><p>روش‌های فعال پرداخت و ارائه‌دهنده‌های مالی در یک نمای مدیریتی.</p></div></div><div className="ops-method-grid">{providers.map(x=><article key={x.provider_key} className="ops-method-card"><span>💳</span><div><b>{x.title||x.provider_key}</b><small>{x.provider_key}</small></div><strong>{x.active?'فعال':'غیرفعال'}</strong></article>)}{!providers.length&&<div className="empty-state">روش پرداختی ثبت نشده است.</div>}</div></section>}

function CommunicationCenter({data,onSend}){const [section,setSection]=useState('inbox'),[to,setTo]=useState(''),[subject,setSubject]=useState(''),[body,setBody]=useState(''),[busy,setBusy]=useState(false),[msg,setMsg]=useState('');const send=async e=>{e.preventDefault();setMsg('');setBusy(true);try{await onSend({recipient:to,subject,body});setMsg('ایمیل در صف ارسال قرار گرفت.');setTo('');setSubject('');setBody('')}catch(e){setMsg(e?.response?.data?.message||e.message||'ارسال انجام نشد')}finally{setBusy(false)}};return <div className="admin-panel communication-center"><div className="panel-title"><div><h2>مرکز پیام و ایمیل</h2><p className="muted">مدیریت پیام‌های کاربران، درخواست‌های تماس، ایمیل‌های در صف و ارسال ایمیل از یک نقطه.</p></div></div><div className="communication-tabs"><button className={section==='inbox'?'active':''} onClick={()=>setSection('inbox')}>📥 پیام‌ها و تماس‌ها</button><button className={section==='email'?'active':''} onClick={()=>setSection('email')}>✉️ ارسال ایمیل</button><button className={section==='outbox'?'active':''} onClick={()=>setSection('outbox')}>📤 خروجی و وضعیت ارسال</button></div>{section==='inbox'&&<div className="communication-grid"><div><h3>پیام‌های مدرس/کاربران</h3>{(data.messages||[]).map(x=><div className="contact-row" key={x.id}><div><b>{x.name||x.userName||x.userId||'کاربر'}</b><span>{x.subject||x.courseId||'پیام'}</span><small>{x.message||x.text||''}</small></div></div>)}{!(data.messages||[]).length&&<div className="empty-state">پیامی ثبت نشده است.</div>}</div><div><h3>درخواست‌های تماس</h3>{(data.contacts||[]).map(x=><div className="contact-row" key={x.id}><div><b>{x.name||'مخاطب'}</b><span>{x.email||x.phone||''} · {x.subject||'درخواست تماس'}</span><small>{x.message||''}</small></div></div>)}{!(data.contacts||[]).length&&<div className="empty-state">درخواست تماسی ثبت نشده است.</div>}</div></div>}{section==='email'&&<form className="communication-compose" onSubmit={send}><div className="form-msg show">گیرنده‌ها را با ویرگول، فاصله یا سمی‌کالن جدا کنید. ایمیل ابتدا در صف قرار می‌گیرد و وضعیت آن در «خروجی» قابل پیگیری است.</div><label className="field"><span>گیرنده ایمیل</span><input value={to} onChange={e=>setTo(e.target.value)} placeholder="user@example.com, user2@example.com" required/></label><label className="field"><span>موضوع</span><input value={subject} onChange={e=>setSubject(e.target.value)} required/></label><label className="field"><span>متن ایمیل</span><textarea rows="10" value={body} onChange={e=>setBody(e.target.value)} required/></label>{msg&&<div className="form-msg show">{msg}</div>}<button className="btn btn-primary" disabled={busy}>{busy?'در حال ثبت در صف...':'ارسال ایمیل'}</button></form>}{section==='outbox'&&<NotificationsPanel value={data.notifications}/>}</div>}
function NotificationsPanel({value,rules,providers,onReload}){const [tab,setTab]=useState('outbox'),[busy,setBusy]=useState(false);const saveRule=async x=>{setBusy(true);try{await updateAdminNotificationRule(x.event_key,{enabled:x.enabled,inApp:x.in_app,email:x.email,sms:x.sms,push:x.push});await onReload()}finally{setBusy(false)}};const saveProvider=async x=>{setBusy(true);try{await updateAdminNotificationProvider(x.provider_key,{active:x.active,config:x.config||{}});await onReload()}finally{setBusy(false)}};return <section className="admin-crm-surface notification-content-surface"><div className="communication-tabs"><button className={tab==='outbox'?'active':''} onClick={()=>setTab('outbox')}>📤 صف ارسال</button><button className={tab==='rules'?'active':''} onClick={()=>setTab('rules')}>⚙️ رویدادها و کانال‌ها</button><button className={tab==='providers'?'active':''} onClick={()=>setTab('providers')}>🔌 سرویس‌دهنده‌ها و درگاه‌ها</button></div>{tab==='outbox'&&<><div className="admin-stat-grid">{(value?.stats||[]).map(x=><div className="admin-stat" key={`${x.channel}-${x.status}`}><span>{x.channel} · {x.status}</span><b>{x.count}</b><small>تعداد</small></div>)}</div>{(value?.items||[]).map(n=><div className="contact-row" key={n.id}><div><b>{n.channel==='sms'?'پیامک':'ایمیل'} · {n.recipient}</b><span>{n.event_key} · تلاش {n.attempts}/{n.max_attempts}</span><small>{n.body}</small></div><strong className={`badge ${n.status==='sent'?'success':''}`}>{n.status==='sent'?'ارسال‌شده':n.status==='failed'?'ناموفق':n.status==='sending'?'در حال ارسال':'در صف'}</strong></div>)}</>}{tab==='rules'&&<div className="notification-rules">{rules.map(x=><div className="notification-rule" key={x.event_key}><div><b>{x.title}</b><span>{x.category} · {x.event_key}</span><small>{x.description}</small></div><div className="notification-channels"><label><input type="checkbox" checked={x.enabled} onChange={e=>saveRule({...x,enabled:e.target.checked})}/> فعال</label><label><input type="checkbox" checked={x.in_app} onChange={e=>saveRule({...x,in_app:e.target.checked})}/> پنل</label><label><input type="checkbox" checked={x.email} onChange={e=>saveRule({...x,email:e.target.checked})}/> ایمیل</label><label><input type="checkbox" checked={x.sms} onChange={e=>saveRule({...x,sms:e.target.checked})}/> پیامک</label></div></div>)}</div>}{tab==='providers'&&<div className="notification-providers">{providers.map(x=><ProviderEditor key={x.provider_key} item={x} busy={busy} onSave={saveProvider}/>)}</div>}</section>}
function ProviderEditor({item,busy,onSave}){const [v,setV]=useState(item);useEffect(()=>setV(item),[item]);const cfg=v.config||{};const set=(k,val)=>setV({...v,config:{...cfg,[k]:val}});const keys=v.provider_key==='zarinpal'?['merchantId','callbackUrl','sandbox']:v.provider_key==='email.smtp'?['host','port','user','password','from','secure']:v.provider_key.includes('sms.')?['apiKey','sender','lineNumber','url','token']:['url','token'];return <article className="provider-card"><div className="provider-head"><div><h3>{v.title}</h3><small>{v.kind} · {v.provider_key}</small></div><label><input type="checkbox" checked={!!v.active} onChange={e=>setV({...v,active:e.target.checked})}/> فعال</label></div><div className="provider-grid">{keys.map(k=><label className="field" key={k}><span>{({merchantId:'Merchant ID',callbackUrl:'Callback URL',sandbox:'Sandbox',host:'SMTP Host',port:'SMTP Port',user:'SMTP User',password:'SMTP Password',from:'From',secure:'TLS/SSL',apiKey:'API Key',sender:'Sender',lineNumber:'Line Number',url:'Endpoint URL',token:'Token'})[k]||k}</span>{k==='sandbox'||k==='secure'?<input type="checkbox" checked={!!cfg[k]} onChange={e=>set(k,e.target.checked)}/>:<input type={/pass|key|token/i.test(k)?'password':'text'} value={cfg[k]==='********'?'':cfg[k]||''} onChange={e=>set(k,e.target.value)} placeholder={cfg[k]==='********'?'••••••••':''}/>}</label>)}</div><button className="btn btn-primary" disabled={busy} onClick={()=>onSave(v)}>ذخیره تنظیمات</button></article>}

function ListPanel({title,items,getTitle,getSub}){return <div className="admin-crm-page"><AdminCrmHeader eyebrow="مرکز مدیریت" title={title} description="اطلاعات این بخش در یک پنل مستقل و قابل پیگیری نمایش داده می‌شود." icon="▦" stats={[{label:'تعداد',value:items.length.toLocaleString('fa-IR')}]} /><section className="admin-crm-surface"><div className="panel-title"><div><h2>{title}</h2><p className="muted">آخرین اطلاعات ثبت‌شده</p></div></div>{items.map(x=><div className="contact-row" key={x.id}><div><b>{getTitle(x)}</b><span>{getSub(x)}</span></div></div>)}</section></div>}
function AnalyticsPanel({d}){return <div className="admin-crm-page"><AdminCrmHeader eyebrow="تحلیل و گزارش" title="آمار بازدید" description="شاخص‌های اصلی سایت و بخش‌های پربازدید را در یک نمای مدیریتی ببینید." icon="◔" stats={[{label:'کل بازدید',value:(d?.total||0).toLocaleString('fa-IR')},{label:'روزهای ثبت‌شده',value:(d?.days?.length||0).toLocaleString('fa-IR')}]} /><div className="admin-crm-grid-2"><section className="admin-crm-surface"><h2>بازدید روزانه</h2>{(d?.days||[]).slice().reverse().map(x=><div className="contact-row" key={x.day}><b>{x.day}</b><span>{x.views} بازدید</span></div>)}</section><section className="admin-crm-surface"><h2>بخش‌های پربازدید</h2>{(d?.sections||[]).map(x=><div className="contact-row" key={x.section}><b>{x.section}</b><span>{x.views} بازدید</span></div>)}</section></div></div>}
function AuditPanel({items}){return <div className="admin-crm-page"><AdminCrmHeader eyebrow="امنیت و رهگیری" title="Audit Log" description="فعالیت‌های مدیریتی و رویدادهای مهم سیستم در یک پنل مستقل." icon="⌁" stats={[{label:'رویدادها',value:items.length.toLocaleString('fa-IR')}]} /><section className="admin-crm-surface"><h2>آخرین فعالیت‌ها</h2>{items.map(x=><div className="contact-row" key={x.id}><b>{x.action}</b><span>{x.role} · {x.userId||'guest'} · {new Date(x.at).toLocaleString('fa-IR')}</span></div>)}</section></div>}
function Messages({items,contact}){return <div className="admin-panel"><h2>{contact?'درخواست‌های تماس':'پیام‌های دانشجویان'}</h2>{items.map(x=><div className="contact-card" key={x.id}><b>{x.name||x.userId||'مخاطب'}</b>{contact&&<div className="contact-meta"><strong>📞 {x.phone||'شماره تماس ثبت نشده'}</strong>{x.email&&<span>✉️ {x.email}</span>}{x.createdAt&&<small>{new Date(x.createdAt).toLocaleString('fa-IR')}</small>}</div>}<strong>{x.subject||x.courseId||'درخواست تماس'}</strong><p>{x.message||x.text}</p>{contact&&x.trackingCode&&<small>کد پیگیری: {x.trackingCode}</small>}</div>)}{!items.length&&<div className="empty-state">{contact?'هنوز درخواست تماسی ثبت نشده است.':'هنوز پیامی ثبت نشده است.'}</div>}</div>}
function ReviewsPanel({items,users,onSave}){const [busyId,setBusyId]=useState(null);return <div className="admin-panel"><div className="panel-title"><div><h2>نظرات کاربران و مهمانان</h2><p className="muted">هر نظر ابتدا نزد مدیر می‌ماند؛ مدیر می‌تواند آن را تأیید کند و برای هر کاربر ارجاع دهد.</p></div></div><div className="admin-list">{items.map(x=>{const assigned=x.assignedTo||'';return <div className="review-admin-row" key={x.id}><div className="review-admin-main"><div className="review-admin-top"><div><b>{x.courseTitle}</b><span>{x.userName} · {new Date(x.createdAt).toLocaleString('fa-IR')}</span></div><span className={`review-status ${x.status||'pending'}`}>{x.status==='approved'?'منتشرشده':x.status==='assigned'?'ارجاع‌شده':'در انتظار بررسی'}</span></div><StarsAdmin value={Number(x.rating)||0}/><p>{x.text}</p>{!x.userId&&<div className="guest-review-contact">مهمان: {x.guestName||"—"}{x.guestEmail&&<> · ایمیل: {x.guestEmail}</>}{x.guestMobile&&<> · موبایل: {x.guestMobile}</>}</div>}</div><div className="review-admin-controls"><label className="field"><span>ارجاع به کاربر / مسئول</span><select value={assigned} onChange={e=>onSave(x.id,{assignedTo:e.target.value||null,status:e.target.value?'assigned':(x.status||'pending'),managerNote:x.managerNote||''})}><option value="">بدون ارجاع</option>{users.filter(u=>u.id!==x.userId).map(u=><option key={u.id} value={u.id}>{u.name} — {u.role}</option>)}</select></label><label className="field"><span>یادداشت مدیر</span><textarea defaultValue={x.managerNote||''} onBlur={e=>onSave(x.id,{managerNote:e.target.value,status:x.status||'pending',assignedTo:x.assignedTo||null})}/></label><div className="row-actions"><button className="btn btn-outline" disabled={busyId===x.id} onClick={async()=>{setBusyId(x.id);try{await onSave(x.id,{status:'approved',assignedTo:x.assignedTo||null,managerNote:x.managerNote||''})}finally{setBusyId(null)}}}>تأیید و انتشار</button>{x.status==='approved'&&<button className="btn btn-outline" disabled={busyId===x.id} onClick={()=>onSave(x.id,{status:'pending',assignedTo:x.assignedTo||null,managerNote:x.managerNote||''})}>بازگشت به بررسی</button>}</div></div></div>})}{!items.length&&<div className="empty-state">هنوز نظری برای بررسی ثبت نشده است.</div>}</div></div>}
function StarsAdmin({value}){return <div className="star-picker admin-stars">{[1,2,3,4,5].map(n=><span key={n} className={n<=value?'star active':'star'}>★</span>)}</div>}
function SiteSettingsPanel({value,onSave,busy}){
 const [v,setV]=useState(value||{}); const [saved,setSaved]=useState('');
 useEffect(()=>setV(value||{}),[value]);
 const set=(path,x)=>{const a=path.split('.');setV(prev=>{const next={...prev};let cur=next;for(let i=0;i<a.length-1;i++){cur[a[i]]={...(cur[a[i]]||{})};cur=cur[a[i]];}cur[a[a.length-1]]=x;return next})};
 const field=(label,path,area=false)=><Field l={label} v={path.split('.').reduce((o,k)=>o?.[k]??'',v)} s={x=>set(path,x)} a={area}/>;
 const save=async()=>{setSaved('');try{await onSave(v);setSaved('تنظیمات با موفقیت ذخیره شد و در سایت قابل مشاهده است.')}catch(e){setSaved(e?.response?.data?.message||e.message||'ذخیره تنظیمات ناموفق بود')}};
 const setLogo=async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{const up=await uploadAdminSiteIcon(f);set('logo',up.data.url)}catch(err){setSaved(err?.response?.data?.message||'آپلود لوگو ناموفق بود')}};
 const setFavicon=async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{const up=await uploadAdminSiteIcon(f);set('favicon',up.data.url)}catch(err){setSaved(err?.response?.data?.message||'آپلود آیکن سایت ناموفق بود')}};
 const sections=[
  ['عمومی','siteName','نام سایت'],['ناوبری','content.global.home','منوی خانه'],['ناوبری','content.global.services','منوی خدمات'],['ناوبری','content.global.portfolio','منوی پورتفولیو'],['ناوبری','content.global.courses','منوی دوره‌ها'],['ناوبری','content.global.subscriptions','منوی اشتراک‌ها'],['ناوبری','content.global.blog','منوی وبلاگ'],['ناوبری','content.global.about','منوی تیم ما'],['ناوبری','content.global.contact','منوی تماس'],['ناوبری','content.global.login','دکمه ورود'],['ناوبری','content.global.cart','دکمه سبد'],['ناوبری','content.global.panel','متن پنل'],['عمومی','tagline','شعار سایت'],['عمومی','phone','شماره تماس'],['عمومی','email','ایمیل'],['عمومی','address','آدرس'],['عمومی','website','دامنه / آدرس سایت'],['عمومی','instagram','اینستاگرام'],['عمومی','telegram','تلگرام'],['عمومی','about','معرفی سایت'],
  ['خانه','content.home.eyebrow','برچسب بالای صفحه'],['خانه','content.home.title','عنوان اصلی'],['خانه','content.home.titleAccent','تأکید عنوان'],['خانه','content.home.description','توضیح اصلی'],['خانه','content.home.primary','دکمه اصلی'],['خانه','content.home.secondary','دکمه دوم'],['خانه','content.home.servicesEyebrow','برچسب خدمات'],['خانه','content.home.servicesTitle','عنوان خدمات'],['خانه','content.home.servicesDescription','توضیح خدمات'],['خانه','content.home.portfolioEyebrow','برچسب نمونه‌کار'],['خانه','content.home.portfolioTitle','عنوان نمونه‌کار'],['خانه','content.home.portfolioDescription','توضیح نمونه‌کار'],['خانه','content.home.processEyebrow','برچسب روش کار'],['خانه','content.home.processTitle','عنوان روش کار'],['خانه','content.home.quoteTitle','متن دعوت به همکاری'],['خانه','content.home.quoteText','متن نقل‌قول'],['خانه','content.home.quoteAttribution','نام گوینده نقل‌قول'],
  ['درباره ما','content.about.kicker','برچسب صفحه'],['درباره ما','content.about.title','عنوان صفحه'],['درباره ما','content.about.description','توضیح صفحه'],['درباره ما','content.about.teamEyebrow','برچسب تیم'],['درباره ما','content.about.teamTitle','عنوان تیم'],['درباره ما','content.about.teamDescription','توضیح تیم'],['درباره ما','content.about.storyEyebrow','برچسب داستان'],['درباره ما','content.about.storyTitle','عنوان داستان'],['درباره ما','content.about.storyDescription','توضیح داستان'],
  ['خدمات','content.services.title','عنوان صفحه'],['خدمات','content.services.description','توضیح صفحه'],['خدمات','content.services.ctaTitle','عنوان دعوت به اقدام'],['خدمات','content.services.ctaDescription','توضیح دعوت به اقدام'],['خدمات','content.services.ctaButton','متن دکمه'],
  ['نمونه‌کارها','content.portfolio.title','عنوان صفحه'],['نمونه‌کارها','content.portfolio.description','توضیح صفحه'],['نمونه‌کارها','content.portfolio.loading','متن بارگذاری'],['نمونه‌کارها','content.portfolio.empty','متن نبود نتیجه'],
  ['دوره‌ها','content.courses.title','عنوان صفحه'],['دوره‌ها','content.courses.description','توضیح صفحه'],['دوره‌ها','content.courses.introEyebrow','برچسب معرفی'],['دوره‌ها','content.courses.introTitle','عنوان معرفی'],['دوره‌ها','content.courses.introDescription','توضیح معرفی'],['دوره‌ها','content.courses.point1','مزیت اول'],['دوره‌ها','content.courses.point2','مزیت دوم'],['دوره‌ها','content.courses.point3','مزیت سوم'],
  ['وبلاگ','content.blog.title','عنوان صفحه'],['وبلاگ','content.blog.description','توضیح صفحه'],['وبلاگ','content.blog.loading','متن بارگذاری'],
  ['تماس','content.contact.title','عنوان صفحه'],['تماس','content.contact.description','توضیح صفحه'],['تماس','content.contact.addressLabel','عنوان آدرس'],['تماس','content.contact.addressValue','متن آدرس'],['تماس','content.contact.phoneLabel','عنوان تلفن'],['تماس','content.contact.phoneValue','متن تلفن'],['تماس','content.contact.emailLabel','عنوان ایمیل'],['تماس','content.contact.emailValue','متن ایمیل'],['تماس','content.contact.hoursLabel','عنوان ساعات'],['تماس','content.contact.hoursValue','متن ساعات'],
  ['فرم تماس','content.contact.formName','برچسب نام'],['فرم تماس','content.contact.formPhone','برچسب تلفن'],['فرم تماس','content.contact.formEmail','برچسب ایمیل'],['فرم تماس','content.contact.formSubject','برچسب موضوع'],['فرم تماس','content.contact.formSelect','متن انتخاب موضوع'],['فرم تماس','content.contact.formMessage','برچسب پیام'],['فرم تماس','content.contact.formPlaceholder','راهنمای پیام'],['فرم تماس','content.contact.formSubmit','دکمه ارسال'],['فرم تماس','content.contact.formSending','متن ارسال'],['فرم تماس','content.contact.formSuccess','پیام موفقیت'],['فرم تماس','content.contact.formError','پیام خطا'],['پاورقی','content.footer.servicesTitle','عنوان خدمات'],['پاورقی','content.footer.companyTitle','عنوان شرکت'],['پاورقی','content.footer.contactTitle','عنوان ارتباط'],['پاورقی','content.footer.copyright','متن کپی‌رایت'],['پاورقی','content.footer.tech','متن تکنولوژی'],['پاورقی','content.footer.services1','خدمت اول'],['پاورقی','content.footer.services2','خدمت دوم'],['پاورقی','content.footer.services3','خدمت سوم'],['پاورقی','content.footer.companyAbout','لینک درباره ما'],['پاورقی','content.footer.companyPortfolio','لینک نمونه‌کارها'],['پاورقی','content.footer.companyBlog','لینک وبلاگ'],['پاورقی','content.footer.contactLink','لینک تماس'],['پاورقی','content.footer.coursesLink','لینک دوره‌ها']
 ];
 return <div className="admin-panel settings-panel settings-v60" dir="rtl">
   <div className="settings-sticky-head"><div><span className="eyebrow">مدیریت محتوای سایت · 6.0.0</span><h2>تنظیمات و متن‌های سایت</h2><p className="muted">متن‌های اصلی صفحات سایت را از همین‌جا ویرایش کنید. تغییرات در PostgreSQL ذخیره می‌شوند.</p></div><button className="btn btn-primary settings-save-top" disabled={busy} onClick={save}>{busy?'در حال ذخیره...':'ذخیره تنظیمات'}</button></div>
   {saved&&<div className={`form-msg show ${saved.includes('ناموفق')?'err':'ok'}`}>{saved}</div>}
   <div className="settings-basic-grid">{field('نام سایت','siteName')}{field('شعار سایت','tagline')}{field('شماره تماس','phone')}{field('ایمیل','email')}{field('آدرس','address',true)}{field('دامنه','website')}{field('اینستاگرام','instagram')}{field('تلگرام','telegram')}{field('معرفی سایت','about',true)}</div>
   <div className="settings-basic-media"><label className="file-field"><span>لوگوی سایت</span><input type="file" accept="image/*" onChange={setLogo}/><small className="upload-hint">تصاویر تا ۱۰ مگابایت.</small></label>{v.logo&&<img src={v.logo} className="settings-logo-preview" alt="logo"/>}<label className="file-field"><span>آیکن سایت / Favicon</span><input type="file" accept="image/*" onChange={setFavicon}/><small className="upload-hint">برای تب مرورگر و میانبر سایت.</small></label>{v.favicon&&<img src={v.favicon} className="settings-favicon-preview" alt="favicon"/>}</div>
   {['خانه','درباره ما','خدمات','نمونه‌کارها','دوره‌ها','وبلاگ','تماس','پاورقی'].map(section=><div className="settings-section-editor" key={section}><div className="settings-section-title"><span>{section}</span><small>متن‌های قابل ویرایش</small></div><div className="settings-editor-grid">{sections.filter(x=>x[0]===section).map(([,path,label])=><div key={path}>{field(label,path,label.includes('توضیح')||label.includes('شرح')||label.includes('معرفی')||label.includes('آدرس')||label.includes('متن')||label.includes('عنوان اصلی'))}</div>)}</div></div>)}
   <div className="settings-bottom-save"><button className="btn btn-primary" disabled={busy} onClick={save}>{busy?'در حال ذخیره...':'ذخیره تنظیمات'}</button></div>
 </div>
}

function EnrollmentPanel({items}){return <div className="admin-panel"><h2>خریدها و پیشرفت دوره</h2>{items.map(x=><div className="contact-row" key={x.id}><div><b>{x.user?.name||'کاربر حذف‌شده'} — {x.course?.title||x.courseId}</b><span>{x.user?.email||''} · پلن {x.plan} · خرید {x.purchase?.paidAt?new Date(x.purchase.paidAt).toLocaleString('fa-IR'):'-'}</span></div><strong>{x.progress||0}%</strong></div>)}</div>}
function PermissionPicker({selected=[],catalog=[],onChange}){const active=new Set(selected||[]);const toggle=k=>{if(k==='*')return onChange(active.has('*')?[]:['*']);if(active.has('*'))return onChange([k]);const next=new Set(active);if(next.has(k))next.delete(k);else next.add(k);onChange([...next])};const groups=catalog.reduce((a,p)=>{const category=p.category||'عمومی';(a[category]??=[]).push(p);return a},{});return <div className="permission-picker"><div className="permission-selected"><div className="permission-selected-head"><strong>دسترسی‌های انتخاب‌شده</strong><small>{active.has('*')?'همه دسترسی‌ها':`${active.size} مورد`}</small></div><div className="permission-chips">{active.has('*')?<span className="permission-chip">همه دسترسی‌ها <button type="button" onClick={()=>toggle('*')}>×</button></span>:Object.entries(groups).length===0&&<span className="muted">هنوز دسترسی انتخاب نشده است.</span>}{!active.has('*')&&[...active].map(k=>{const p=catalog.find(x=>x.key===k);return <span className="permission-chip" key={k}>{p?.title||k}<small>{k}</small><button type="button" onClick={()=>toggle(k)}>×</button></span>})}</div></div><div className="permission-catalog"><div className="permission-selected-head"><strong>انتخاب دسترسی</strong><small>برای افزودن کلیک کنید</small></div><button type="button" className={active.has('*')?'permission-option selected':'permission-option'} onClick={()=>toggle('*')}><span><b>دسترسی کامل</b><small>همه دسترسی‌های ثبت‌شده</small></span><i>{active.has('*')?'✓':'+'}</i></button>{Object.entries(groups).map(([category,list])=><div className="permission-group" key={category}><h4>{category}</h4>{list.map(p=><button type="button" className={active.has(p.key)?'permission-option selected':'permission-option'} key={p.key} onClick={()=>toggle(p.key)}><span><b>{p.title}</b><small>{p.key}{p.description?` · ${p.description}`:''}</small></span><i>{active.has(p.key)?'✓':'+'}</i></button>)}</div>)}</div></div>}
function Editor({item,busy,close,save,saveRole,courses,roles,permissions}){const [v,setV]=useState(item);const set=(k,x)=>setV({...v,[k]:x});const upload=async(e,k,multi=false)=>{const files=[...(e.target.files||[])];e.target.value='';if(!files.length)return;try{const out=await Promise.all(files.map(async f=>{if(k==='images'){const r=await uploadAdminFile(f);return r.data.url;}return readFile(f)}));set(k,multi?[...(v[k]||[]),...out]:out[0])}catch(err){alert(err?.response?.data?.message||'آپلود فایل ناموفق بود')}};const setUserResume=async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{const r=await uploadAdminFile(f);set('profile',{...v.profile,resume:r.data.url})}catch(err){alert(err?.response?.data?.message||'آپلود رزومه ناموفق بود')}};const setTeamResume=async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{const r=await uploadAdminFile(f);set('resume',r.data.url)}catch(err){alert(err?.response?.data?.message||'آپلود فایل ناموفق بود')}};const setTeamPhoto=async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{const r=await uploadAdminProfileImage(f);set('photo',r.data.url)}catch(err){alert(err?.response?.data?.message||'آپلود عکس ناموفق بود')}};const setUserPhoto=async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{const r=await uploadAdminProfileImage(f);set('profile',{...v.profile,photo:r.data.url})}catch(err){alert(err?.response?.data?.message||'آپلود عکس ناموفق بود')}};const setLessonVideo=(e,i)=>{const f=e.target.files?.[0];if(!f)return;readFile(f).then(video=>set('lessons',v.lessons.map((z,j)=>j===i?{...z,video}:z)))};if(v.__role)return <Modal title={v.key?'ویرایش نقش':'نقش جدید'} close={close}><Field l="کلید نقش" v={v.key} s={x=>set('key',x)} disabled={!!item.key}/><Field l="عنوان" v={v.title} s={x=>set('title',x)}/><PermissionPicker selected={v.permissions||[]} catalog={permissions} onChange={x=>set('permissions',x)}/><SaveButton busy={busy} onClick={()=>saveRole(v)}/></Modal>;
if(v.__plan)return <Modal title={v.key?'ویرایش پلن':'پلن جدید'} close={close}><label className="field"><span>دوره</span><select value={v.courseId||''} onChange={e=>set('courseId',e.target.value)}>{courses.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><Field l="کلید پلن" v={v.key} s={x=>set('key',x)} disabled={!!item.key}/><Field l="عنوان پلن" v={v.title} s={x=>set('title',x)}/><Field l="قیمت" v={v.price} s={x=>set('price',x)}/><Field l="امکانات با کاما" v={(v.features||[]).join(', ')} s={x=>set('features',x.split(',').map(x=>x.trim()).filter(Boolean))}/><label className="check-field"><input type="checkbox" checked={!!v.free} onChange={e=>set('free',e.target.checked)}/> رایگان</label><label className="check-field"><input type="checkbox" checked={v.guestAllowed!==false} onChange={e=>set('guestAllowed',e.target.checked)}/> قابل استفاده برای مهمان</label><SaveButton busy={busy} onClick={()=>savePlan(v)}/></Modal>;
if(v.__service)return <Modal title={v.id?'ویرایش خدمت':'خدمت جدید'} close={close}><Field l="عنوان" v={v.title} s={x=>set('title',x)}/><Field l="خلاصه" v={v.summary} s={x=>set('summary',x)} a/><Field l="توضیحات" v={v.description} s={x=>set('description',x)} a/><Field l="آیکن" v={v.icon} s={x=>set('icon',x)}/><Field l="ویژگی‌ها با کاما" v={(v.features||[]).join(', ')} s={x=>set('features',x.split(',').map(x=>x.trim()).filter(Boolean))}/><SaveButton busy={busy} onClick={()=>save(v,'services')}/></Modal>;
if(v.__blog)return <Modal title={v.id?'ویرایش مقاله':'مقاله جدید'} close={close}><Field l="عنوان" v={v.title} s={x=>set('title',x)}/><Field l="خلاصه" v={v.excerpt} s={x=>set('excerpt',x)} a/><Field l="محتوای کامل" v={v.content} s={x=>set('content',x)} a/><Field l="نویسنده" v={v.author} s={x=>set('author',x)}/><Field l="تاریخ" v={v.date} s={x=>set('date',x)}/><Field l="برچسب‌ها با کاما" v={(v.tags||[]).join(', ')} s={x=>set('tags',x.split(',').map(x=>x.trim()).filter(Boolean))}/><Field l="زمان مطالعه" v={v.readTime} s={x=>set('readTime',x)}/><SaveButton busy={busy} onClick={()=>save(v,'blog')}/></Modal>;
if(v.__user&&v.__newUser)return <Modal title="ایجاد کاربر جدید" close={close} stickySave={true}><div className="user-sticky-save"><SaveButton busy={busy} onClick={async()=>{try{await createAdminUser({name:v.name,username:v.username,email:v.email,phone:v.phone,password:v.password,role:v.role,permissions:v.permissions,status:v.status,profile:v.profile});close();location.reload()}catch(e){alert(e?.response?.data?.message||e?.message||'ایجاد کاربر ناموفق بود')}}}/></div><Field l="نام و نام خانوادگی" v={v.name} s={x=>set('name',x)}/><Field l="نام کاربری" v={v.username} s={x=>set('username',x)}/><Field l="ایمیل" v={v.email} s={x=>set('email',x)}/><Field l="موبایل" v={v.phone} s={x=>set('phone',x)}/><Field l="رمز عبور" v={v.password} s={x=>set('password',x)}/><label className="field"><span>نقش</span><select value={v.role||'user'} onChange={e=>set('role',e.target.value)}>{roles.map(r=><option key={r.key} value={r.key}>{r.title}</option>)}</select></label><PermissionPicker selected={v.permissions||[]} catalog={permissions} onChange={x=>set('permissions',x)}/><label className="field"><span>وضعیت</span><select value={v.status||'active'} onChange={e=>set('status',e.target.value)}><option value="active">فعال</option><option value="suspended">تعلیق‌شده</option></select></label></Modal>;
if(v.__user)return <Modal title="ویرایش کاربر" close={close}><Field l="نام" v={v.name} s={x=>set('name',x)}/><Field l="نام کاربری" v={v.username} s={x=>set('username',x)}/><Field l="ایمیل" v={v.email} s={x=>set('email',x)}/><Field l="رمز عبور جدید" v={v.password||''} s={x=>set('password',x)}/><small className="muted">اگر رمز جدید وارد نشود، رمز فعلی حفظ می‌شود.</small><Field l="موبایل" v={v.phone} s={x=>set('phone',x)}/><label className="field"><span>نقش</span><select value={v.role||'user'} onChange={e=>set('role',e.target.value)}>{roles.map(r=><option key={r.key} value={r.key}>{r.title}</option>)}</select></label><PermissionPicker selected={v.permissions||[]} catalog={permissions} onChange={x=>set('permissions',x)}/><label className="field"><span>وضعیت</span><select value={v.status||'active'} onChange={e=>set('status',e.target.value)}><option value="active">فعال</option><option value="suspended">تعلیق‌شده</option></select></label><Field l="دلیل تعلیق" v={v.suspensionReason} s={x=>set('suspensionReason',x)}/><Field l="تعلیق تا (ISO)" v={v.suspendedUntil} s={x=>set('suspendedUntil',x)}/><Field l="بیوگرافی" v={v.profile?.bio} s={x=>set('profile',{...v.profile,bio:x})} a/><label className="file-field"><span>عکس پروفایل</span><input type="file" accept="image/*" onChange={setUserPhoto}/>{v.profile?.photo&&<img className="profile-photo-preview" src={v.profile.photo} alt=""/>}</label><label className="file-field"><span>رزومه / فایل حرفه‌ای</span><input type="file" onChange={setUserResume}/><small className="upload-hint">فرمت فایل آزاد، حداکثر ۲۵ مگابایت.</small></label><SaveButton busy={busy} onClick={async()=>{await updateAdminUser(v.id,{name:v.name,username:v.username,email:v.email,phone:v.phone,password:v.password||'',role:v.role,permissions:v.permissions,status:v.status,suspensionReason:v.suspensionReason,suspendedUntil:v.suspendedUntil,profile:v.profile});close();location.reload()}}/></Modal>;
return <Modal title={v.id?'ویرایش':'ایجاد'} close={close}>{item.id&&<input type="hidden"/>}{item.category!==undefined&&<><Field l="عنوان" v={v.title} s={x=>set('title',x)}/><Field l="مشتری" v={v.client} s={x=>set('client',x)}/><Field l="دموی آنلاین" v={v.demoUrl} s={x=>set('demoUrl',x)}/><Field l="لینک سایت عملیاتی مشتری" v={v.liveUrl} s={x=>set('liveUrl',x)}/><Field l="متن دکمه سایت مشتری" v={v.liveLabel} s={x=>set('liveLabel',x)}/><Field l="توضیح" v={v.summary} s={x=>set('summary',x)} a/><Field l="تکنولوژی‌ها با کاما" v={(v.stack||[]).join(', ')} s={x=>set('stack',x.split(',').map(y=>y.trim()).filter(Boolean))}/><label className="file-field"><span>تصاویر</span><input type="file" accept="image/*" multiple onChange={e=>upload(e,'images',true)}/></label></>}{item.role!==undefined&&!item.__user&&item.category===undefined&&<><Field l="نام" v={v.name} s={x=>set('name',x)}/><Field l="سمت" v={v.role} s={x=>set('role',x)}/><Field l="بیوگرافی" v={v.bio} s={x=>set('bio',x)} a/><Field l="سابقه" v={v.experience} s={x=>set('experience',x)}/><Field l="تحصیلات" v={v.education} s={x=>set('education',x)}/><Field l="مهارت‌ها با کاما" v={(v.skills||[]).join(', ')} s={x=>set('skills',x.split(',').map(y=>y.trim()).filter(Boolean))}/><label className="file-field"><span>عکس عضو تیم</span><input type="file" accept="image/*" onChange={setTeamPhoto}/>{v.photo&&<img className="profile-photo-preview" src={v.photo} alt=""/>}</label><label className="file-field"><span>رزومه / فایل حرفه‌ای</span><input type="file" onChange={setTeamResume}/><small className="upload-hint">فرمت فایل آزاد، حداکثر ۲۵ مگابایت.</small></label></>}{item.plans!==undefined&&item.category===undefined&&item.role===undefined&&<><Field l="عنوان دوره" v={v.title} s={x=>set('title',x)}/><div className="editor-grid"><Field l="سطح" v={v.level} s={x=>set('level',x)}/><Field l="مدت" v={v.duration} s={x=>set('duration',x)}/><label className="field"><span>نوع دوره</span><select value={v.courseType||'paid'} onChange={e=>set('courseType',e.target.value)}><option value="free">رایگان</option><option value="paid">پولی</option><option value="vip">VIP</option></select></label></div><div className="admin-panel nested access-editor"><h3>طرح‌های مجاز برای دسترسی</h3><p className="muted">مشخص کنید این دوره برای کدام حساب‌ها قابل استفاده باشد.</p>{[['free','رایگان'],['normal','عادی'],['vip','VIP']].map(([key,label])=><label className="check-field" key={key}><input type="checkbox" checked={(v.allowedPlans||[]).includes(key)} onChange={e=>set('allowedPlans',e.target.checked?[...(v.allowedPlans||[]),key]:(v.allowedPlans||[]).filter(x=>x!==key))}/>{label}</label>)}</div><Field l="معرفی کامل دوره" v={v.introduction} s={x=>set('introduction',x)} a/><Field l="خلاصه" v={v.summary} s={x=>set('summary',x)} a/><Field l="موضوعات با کاما" v={(v.topics||[]).join(', ')} s={x=>set('topics',x.split(',').map(y=>y.trim()).filter(Boolean))}/><div className="admin-panel nested"><h3>پلن‌های این دوره</h3>{(v.plans||[]).map((p,i)=><div className="plan-inline" key={p.key}><Field l="عنوان" v={p.title} s={x=>set('plans',v.plans.map((z,j)=>j===i?{...z,title:x}:z))}/><Field l="قیمت" v={p.price} s={x=>set('plans',v.plans.map((z,j)=>j===i?{...z,price:x}:z))}/><button className="icon-btn danger" title="حذف پلن" onClick={()=>set('plans',v.plans.filter((_,j)=>j!==i))}>{icons.delete}</button></div>)}<button className="btn btn-outline" onClick={()=>set('plans',[...(v.plans||[]),{key:`plan_${Date.now()}`,title:'پلن جدید',price:'رایگان',features:[],free:false,guestAllowed:false}])}>+ افزودن پلن</button></div><label className="file-field"><span>ویدئوی معرفی دوره (به‌صورت پیش‌فرض در صفحه درس)</span><input type="file" accept="video/*" onChange={e=>{const f=e.target.files?.[0];if(f)readFile(f).then(video=>set('introVideo',video))}}/></label>{v.introVideo&&<div className="badge">ویدئوی معرفی آماده است</div>}<div className="panel-title"><h3>جلسات</h3><button className="btn btn-outline" onClick={()=>set('lessons',[...(v.lessons||[]),{id:'l_'+Date.now(),title:'جلسه جدید',duration:'20 دقیقه',video:'',free:false}])}>+ جلسه</button></div>{(v.lessons||[]).map((l,i)=><div className="lesson-editor" key={l.id}><Field l={`عنوان جلسه ${i+1}`} v={l.title} s={x=>set('lessons',v.lessons.map((z,j)=>j===i?{...z,title:x}:z))}/><label className="check-field"><input type="checkbox" checked={!!l.free} onChange={e=>set('lessons',v.lessons.map((z,j)=>j===i?{...z,free:e.target.checked}:z))}/> رایگان برای مهمان</label><label className="file-field"><span>ویدئو</span><input type="file" accept="video/*" onChange={e=>setLessonVideo(e,i)}/></label></div>)}</>}<SaveButton busy={busy} onClick={()=>save(v,item.category!==undefined?'portfolio':item.role!==undefined?'team':item.__service?'services':item.__blog?'blog':'courses')}/></Modal>}
function Modal({title,close,children,stickySave=false}){return <div className="modal-backdrop"><div className={`editor-modal ${stickySave?'user-editor-modal':''}`}><div className="panel-title"><h2>{title}</h2><button className="icon-btn" onClick={close}>×</button></div>{children}</div></div>}
function SaveButton({busy,onClick}){return <button className="btn btn-primary full-btn" disabled={busy} onClick={onClick}>{busy?'در حال ذخیره...':'ذخیره'}</button>}
function Field({l,v,s,a,disabled}){return <label className="field"><span>{l}</span>{a?<textarea disabled={disabled} value={v||''} onChange={e=>s(e.target.value)}/>:<input disabled={disabled} value={v||''} onChange={e=>s(e.target.value)}/>}</label>}
async function savePlan(v){return v.__existing?updateAdminPlan(v.courseId,v.key,{title:v.title,price:v.price,features:v.features,free:v.free,guestAllowed:v.guestAllowed}):createAdminPlan(v.courseId,v)}


function CRMPanel({items,users,report,onReload,onOpen,contracts,contractReport}){
 const [view,setView]=useState('dashboard'),[editing,setEditing]=useState(null),[activity,setActivity]=useState(null),[activities,setActivities]=useState([]),[busy,setBusy]=useState(false),[q,setQ]=useState(''),[status,setStatus]=useState('all'),[owner,setOwner]=useState('all'),[type,setType]=useState('all');
 const statuses=[['all','همه'],['new','جدید'],['qualified','ارزیابی‌شده'],['active','در حال مذاکره'],['won','تبدیل‌شده'],['lost','از دست‌رفته']];
 const statusText=Object.fromEntries(statuses);
 const filtered=items.filter(x=>(status==='all'||x.status===status)&&(owner==='all'||String(x.owner_id||'')===owner)&&(type==='all'||x.type===type)&&[x.name,x.company,x.email,x.phone,x.status,x.source,x.owner_username].join(' ').toLowerCase().includes(q.toLowerCase()));
 const summary=report?.summary||{},total=Number(summary.total||0),leads=Number(summary.leads||0),customers=Number(summary.customers||0),openTickets=Number(report?.openTickets||0);
 const stageCount=k=>Number(report?.statuses?.find(x=>x.status===k)?.count||0);
 const activityTotal=(report?.activities||[]).reduce((n,x)=>n+Number(x.count||0),0);
 const activityLabels={note:'یادداشت',call:'تماس',email:'ایمیل',meeting:'جلسه',task:'وظیفه',followup:'پیگیری'};
 const ownerList=(report?.owners||[]).slice(0,6);
 const recent=[...items].sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0)).slice(0,7);
 const save=async()=>{if(!editing?.name?.trim())return;setBusy(true);try{if(editing.id)await updateAdminCRM(editing.id,editing);else await createAdminCRM(editing);setEditing(null);await onReload()}catch(e){alert(e?.response?.data?.message||e.message||'ذخیره مخاطب ناموفق بود')}finally{setBusy(false)}};
 const openTimeline=async c=>{setActivity(c);try{const r=await getCRMTimeline(c.id);setActivities(r.data||[])}catch(e){setActivities([])}};
 const addNote=async()=>{const body=prompt('متن فعالیت را وارد کنید:');if(!body||!activity)return;await addCRMActivity(activity.id,{type:'note',subject:'یادداشت مدیر',body});await openTimeline(activity);await onReload()};
 const newContact=()=>setEditing({name:'',company:'',email:'',phone:'',type:'lead',status:'new',source:'',ownerId:'',username:'',password:'',tags:[],notes:''});
 const goContacts=(nextStatus='all')=>{setStatus(nextStatus);setView('contacts')};
 return <div className="crm50 crm51 crm51-redesign" dir="rtl">
   <aside className="crm50-side">
    <div className="crm50-side-brand"><span className="crm50-logo">C</span><div><b>CRM</b><small>مرکز ارتباط با مشتری</small></div></div>
    <div className="crm50-side-label">فضای کاری</div>
    <button className={view==='dashboard'?'active':''} onClick={()=>setView('dashboard')}><span>▦</span>نمای کلی</button>
    <button className={view==='pipeline'?'active':''} onClick={()=>setView('pipeline')}><span>◫</span>فرآیند فروش</button>
    <button className={view==='contacts'?'active':''} onClick={()=>setView('contacts')}><span>◎</span>مشتریان و سرنخ‌ها</button>
    <button className={view==='contracts'?'active':''} onClick={()=>onOpen?.('contracts')}><span>□</span>قراردادها</button>
    <button className={view==='activity'?'active':''} onClick={()=>setView('activity')}><span>◷</span>فعالیت‌ها</button>
    <button onClick={()=>onOpen?.('tickets')}><span>▤</span>تیکت‌ها</button>
    <div className="crm50-side-spacer"/>
    <div className="crm50-side-note"><b>کنترل سریع</b><span>تمام عملیات CRM بر اساس نقش و دسترسی کاربر کنترل می‌شود.</span></div>
   </aside>
   <main className="crm50-main">
    <header className="crm50-topbar">
      <div><div className="crm50-breadcrumb">مدیریت ارتباط با مشتری <i>/</i> {view==='dashboard'?'نمای کلی':view==='pipeline'?'فرآیند فروش':view==='contacts'?'مخاطبین':view==='activity'?'فعالیت‌ها':'CRM'}</div><h1>مرکز فرمان ارتباط با مشتری</h1></div>
      <div className="crm50-actions"><button className="crm50-secondary" onClick={()=>onOpen?.('tickets')}>مشاهده تیکت‌ها</button><button className="crm50-primary" onClick={newContact}>+ ثبت مخاطب جدید</button></div>
    </header>
    <div className="crm50-toolbar"><div className="crm50-search"><span>⌕</span><input value={q} onChange={e=>setQ(e.target.value)} placeholder="جستجوی سریع نام، شرکت، تلفن یا ایمیل..."/></div><button className="crm50-tool" onClick={()=>goContacts('new')}>سرنخ‌های جدید <b>{stageCount('new').toLocaleString('fa-IR')}</b></button><button className="crm50-tool" onClick={()=>goContacts('active')}>مذاکره <b>{stageCount('active').toLocaleString('fa-IR')}</b></button><button className="crm50-tool" onClick={()=>onOpen?.('contracts')}>قرارداد <b>{Number(contractReport?.summary?.waiting||0).toLocaleString('fa-IR')}</b></button></div>

    {view==='dashboard'&&<>
      <section className="crm50-kpis"><div className="crm50-kpi primary"><small>کل پرونده‌ها</small><strong>{total.toLocaleString('fa-IR')}</strong><span>مخاطبین ثبت‌شده در CRM</span></div><div className="crm50-kpi"><small>سرنخ فروش</small><strong>{leads.toLocaleString('fa-IR')}</strong><span>پرونده‌هایی که هنوز تبدیل نشده‌اند</span></div><div className="crm50-kpi"><small>مشتریان</small><strong>{customers.toLocaleString('fa-IR')}</strong><span>مشتریان فعال و ثبت‌شده</span></div><div className="crm50-kpi"><small>تیکت باز</small><strong>{openTickets.toLocaleString('fa-IR')}</strong><span>نیازمند رسیدگی تیم</span></div></section>
      <section className="crm50-workgrid">
        <article className="crm50-surface crm50-pipeline"><div className="crm50-surface-head"><div><small>فرآیند فروش</small><h2>قیف فروش</h2><p>مراحل فروش را ببینید و با یک کلیک پرونده‌های هر مرحله را باز کنید.</p></div><button onClick={()=>setView('pipeline')}>مشاهده فرآیند ←</button></div><div className="crm50-pipeline-track">{statuses.slice(1,5).map(([key,label],i)=>{const n=stageCount(key);return <button key={key} onClick={()=>goContacts(key)} className="crm50-stage"><div className="crm50-stage-top"><span>{String(i+1).padStart(2,'0')}</span><b>{label}</b><strong>{n.toLocaleString('fa-IR')}</strong></div><div className="crm50-stage-bar"><i style={{width:`${Math.max(n?8:0,total?Math.round(n/total*100):0)}%`}}/></div><small>{total?Math.round(n/total*100):0}٪ از کل پرونده‌ها</small></button>})}</div></article>
        <article className="crm50-surface crm50-focus"><div className="crm50-surface-head"><div><small>تمرکز امروز</small><h2>صف کار تیم</h2></div></div><button onClick={()=>goContacts('new')}><span>01</span><div><b>سرنخ‌های جدید</b><small>{stageCount('new').toLocaleString('fa-IR')} مورد</small></div><em>←</em></button><button onClick={()=>goContacts('active')}><span>02</span><div><b>مذاکره‌های جاری</b><small>{stageCount('active').toLocaleString('fa-IR')} مورد</small></div><em>←</em></button><button onClick={()=>onOpen?.('contracts')}><span>03</span><div><b>قراردادهای منتظر امضا</b><small>{Number(contractReport?.summary?.waiting||0).toLocaleString('fa-IR')} مورد</small></div><em>←</em></button><button onClick={()=>onOpen?.('tickets')}><span>04</span><div><b>تیکت‌های باز</b><small>{openTickets.toLocaleString('fa-IR')} مورد</small></div><em>←</em></button></article>
      </section>
      <section className="crm50-workgrid lower"><article className="crm50-surface"><div className="crm50-surface-head"><div><small>پرونده‌های اخیر</small><h2>آخرین مخاطبین</h2></div><button onClick={()=>setView('contacts')}>همه مخاطبین ←</button></div><div className="crm50-recent-list">{recent.map(c=><button key={c.id} onClick={()=>openTimeline(c)}><i>{(c.name||'?').trim().charAt(0)}</i><div><b>{c.name||'بدون نام'}</b><small>{c.company||c.email||c.phone||'بدون اطلاعات تماس'}</small></div><span>{c.type==='customer'?'مشتری':c.type==='partner'?'همکار':'سرنخ'}</span><strong>{statusText[c.status]||c.status||'—'}</strong></button>)}{!recent.length&&<div className="crm50-empty">مخاطبی ثبت نشده است.</div>}</div></article><article className="crm50-surface crm50-owners"><div className="crm50-surface-head"><div><small>توزیع مسئولیت</small><h2>بار کاری تیم</h2></div></div>{ownerList.map((x,i)=><div className="crm50-owner" key={x.owner}><span><i>{i+1}</i>{x.owner}</span><b>{Number(x.count||0).toLocaleString('fa-IR')}</b></div>)}{!ownerList.length&&<div className="crm50-empty">اطلاعات مسئولیت هنوز ثبت نشده است.</div>}</article></section>
    </>}

    {view==='pipeline'&&<section className="crm50-surface crm50-full"><div className="crm50-surface-head"><div><small>فرآیند فروش</small><h2>مدیریت قیف فروش</h2><p>هر مرحله یک نمای عملیاتی از پرونده‌های فروش است.</p></div><button className="crm50-primary small" onClick={newContact}>+ پرونده جدید</button></div><div className="crm50-kanban">{statuses.slice(1,5).map(([key,label])=><div className="crm50-column" key={key}><div className="crm50-column-head"><span>{label}</span><b>{stageCount(key).toLocaleString('fa-IR')}</b></div>{items.filter(x=>x.status===key).slice(0,8).map(c=><button key={c.id} onClick={()=>openTimeline(c)}><div><i>{(c.name||'?').charAt(0)}</i><strong>{c.name||'بدون نام'}</strong></div><small>{c.company||c.phone||c.email||'بدون اطلاعات'}</small><em>{c.owner_username||'بدون مسئول'}</em></button>)}{!items.some(x=>x.status===key)&&<div className="crm50-column-empty">پرونده‌ای در این مرحله نیست</div>}</div>)}</div></section>}

    {view==='contacts'&&<section className="crm50-surface crm50-full"><div className="crm50-surface-head"><div><small>پرونده ۳۶۰ درجه</small><h2>مشتریان و سرنخ‌ها</h2><p>{filtered.length.toLocaleString('fa-IR')} پرونده مطابق فیلتر فعلی</p></div><button className="crm50-primary small" onClick={newContact}>+ مخاطب جدید</button></div><div className="crm50-filters"><div className="crm50-search wide"><span>⌕</span><input value={q} onChange={e=>setQ(e.target.value)} placeholder="نام، شرکت، ایمیل یا تلفن"/></div><select value={type} onChange={e=>setType(e.target.value)}><option value="all">همه انواع</option><option value="lead">سرنخ</option><option value="customer">مشتری</option><option value="partner">همکار</option></select><select value={status} onChange={e=>setStatus(e.target.value)}>{statuses.map(x=><option key={x[0]} value={x[0]}>{x[1]}</option>)}</select><select value={owner} onChange={e=>setOwner(e.target.value)}><option value="all">همه مسئولان</option>{users.filter(u=>['admin','employee','teacher'].includes(u.role)).map(u=><option key={u.id} value={u.id}>{u.username}</option>)}</select><button onClick={()=>{setQ('');setStatus('all');setOwner('all');setType('all')}}>پاک‌سازی فیلتر</button></div><div className="crm50-table"><div className="crm50-table-head"><span>مخاطب</span><span>نوع</span><span>مرحله</span><span>مسئول</span><span>عملیات</span></div>{filtered.map(c=><div className="crm50-table-row" key={c.id}><div className="crm50-person"><i>{(c.name||'?').trim().charAt(0)}</i><span><b>{c.name||'بدون نام'}</b><small>{c.company||c.email||c.phone||'بدون اطلاعات تماس'}</small></span></div><span>{c.type==='customer'?'مشتری':c.type==='partner'?'همکار':'سرنخ'}</span><strong>{statusText[c.status]||c.status||'—'}</strong><span>{c.owner_username||'بدون مسئول'}</span><div><button onClick={()=>openTimeline(c)}>پرونده</button><button onClick={()=>setEditing({...c,ownerId:c.owner_id||''})}>ویرایش</button></div></div>)}{!filtered.length&&<div className="crm50-empty">مخاطبی مطابق فیلتر پیدا نشد.</div>}</div></section>}

    {view==='activity'&&<section className="crm50-surface crm50-full"><div className="crm50-surface-head"><div><small>تعاملات</small><h2>مرکز فعالیت‌های CRM</h2><p>{activityTotal.toLocaleString('fa-IR')} تعامل ثبت‌شده بر اساس گزارش CRM</p></div></div><div className="crm50-activity-dashboard"><div className="crm50-activity-total"><strong>{activityTotal.toLocaleString('fa-IR')}</strong><span>کل تعاملات</span></div>{(report?.activities||[]).map(a=>{const n=Number(a.count||0),max=Math.max(1,...(report?.activities||[]).map(x=>Number(x.count||0)));return <div className="crm50-activity-line" key={a.type}><span>{activityLabels[a.type]||a.type}</span><div><i style={{width:`${Math.max(n?6:0,n/max*100)}%`}}/></div><b>{n.toLocaleString('fa-IR')}</b></div>})}{!(report?.activities||[]).length&&<div className="crm50-empty">هنوز فعالیتی ثبت نشده است.</div>}</div></section>}

    {activity&&<div className="crm50-modal"><div className="crm50-modal-card"><div className="crm50-modal-head"><div><small>پرونده مشتری</small><h3>{activity.name}</h3></div><button onClick={()=>setActivity(null)}>×</button></div><div className="crm50-timeline">{activities.map(a=><div key={a.id}><i/><div><b>{a.subject||a.type}</b><small>{new Date(a.created_at).toLocaleString('fa-IR')}</small><p>{a.body||'—'}</p></div></div>)}{!activities.length&&<div className="crm50-empty">هنوز فعالیتی برای این مشتری ثبت نشده است.</div>}</div><button className="crm50-primary full" onClick={addNote}>+ ثبت یادداشت جدید</button></div></div>}
    {editing&&<div className="crm50-modal"><div className="crm50-modal-card"><div className="crm50-modal-head"><div><small>پرونده CRM</small><h3>{editing.id?'ویرایش مخاطب':'ثبت مخاطب جدید'}</h3></div><button onClick={()=>setEditing(null)}>×</button></div><div className="crm50-form"><Field l="نام و نام خانوادگی" v={editing.name} s={v=>setEditing({...editing,name:v})}/><Field l="شرکت" v={editing.company} s={v=>setEditing({...editing,company:v})}/><Field l="ایمیل" v={editing.email} s={v=>setEditing({...editing,email:v})}/><Field l="تلفن" v={editing.phone} s={v=>setEditing({...editing,phone:v})}/><label className="field"><span>نوع</span><select value={editing.type||'lead'} onChange={e=>setEditing({...editing,type:e.target.value})}><option value="lead">سرنخ</option><option value="customer">مشتری</option><option value="partner">همکار</option></select></label>{editing.type==='customer'&&<><Field l="نام کاربری مشتری" v={editing.username||''} s={v=>setEditing({...editing,username:v})}/><Field l={editing.id?'رمز عبور جدید':'رمز عبور مشتری'} v={editing.password||''} s={v=>setEditing({...editing,password:v})}/><small className="muted crm-account-note">ورود مشتری از صفحه ورود اصلی سایت انجام می‌شود. در ویرایش، خالی گذاشتن رمز یعنی حفظ رمز قبلی.</small></>}<label className="field"><span>مرحله فروش</span><select value={editing.status||'new'} onChange={e=>setEditing({...editing,status:e.target.value})}>{statuses.slice(1).map(x=><option key={x[0]} value={x[0]}>{x[1]}</option>)}</select></label><label className="field"><span>مسئول پرونده / ارجاع به</span><select value={editing.ownerId||editing.owner_id||""} onChange={e=>setEditing({...editing,ownerId:e.target.value})}><option value="">بدون مسئول</option>{users.filter(u=>u.status!=='suspended').map(u=><option key={u.id} value={u.id}>{u.name||u.username} · {u.role}</option>)}</select></label><Field l="یادداشت" v={editing.notes} s={v=>setEditing({...editing,notes:v})} a/></div><button className="crm50-primary full" disabled={busy} onClick={save}>{busy?'در حال ذخیره...':'ذخیره پرونده'}</button></div></div>}
   </main>
  </div>;
}

function ContractCharts({report}){
 const categories=Array.isArray(report?.categories)?report.categories:[];
 const rawTrend=Array.isArray(report?.trend)?report.trend:[];
 const trend=rawTrend.map(x=>({date:x.date_day||x.day,count:Number(x.count||0)}));
 const max=Math.max(1,...trend.map(x=>x.count));
 const maxCat=Math.max(1,...categories.map(x=>Number(x.count||0)));
 const categoryLabels={training:'آموزش',consulting:'مشاوره',design:'طراحی سایت',development:'توسعه نرم‌افزار',maintenance:'پشتیبانی و نگهداری',general:'عمومی'};
 const points=trend.map((x,i)=>{const px=4+(trend.length===1?46:i*92/(trend.length-1));const py=96-(x.count/max)*76;return [px,py]});
 const path=points.map((p,i)=>`${i?'L':'M'} ${p[0]} ${p[1]}`).join(' ');
 return <div className="contract-charts">
   <section className="contract-chart-card"><div className="contract-chart-head"><div><span>روند ثبت قرارداد</span><h3>۳۰ روز اخیر</h3></div><b>{trend.reduce((n,x)=>n+x.count,0).toLocaleString('fa-IR')} قرارداد</b></div>
     {trend.length?<div className="contract-trend-wrap"><svg className="contract-trend" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="روند ثبت قرارداد در ۳۰ روز اخیر"><line x1="4" y1="96" x2="96" y2="96"/><line x1="4" y1="58" x2="96" y2="58"/><line x1="4" y1="20" x2="96" y2="20"/>{path&&<path d={path} fill="none" stroke="currentColor" strokeWidth="2.2" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round"/>}{points.map((p,i)=><circle key={i} cx={p[0]} cy={p[1]} r="1.7" fill="currentColor" vectorEffect="non-scaling-stroke"><title>{new Date(trend[i].date).toLocaleDateString('fa-IR')} · {trend[i].count.toLocaleString('fa-IR')} قرارداد</title></circle>)}</svg><div className="contract-trend-labels"><span>{trend[0]?.date?new Date(trend[0].date).toLocaleDateString('fa-IR'):''}</span><span>{trend[Math.floor(trend.length/2)]?.date?new Date(trend[Math.floor(trend.length/2)].date).toLocaleDateString('fa-IR'):''}</span><span>{trend.at(-1)?.date?new Date(trend.at(-1).date).toLocaleDateString('fa-IR'):''}</span></div></div>:<div className="contract-chart-empty">در ۳۰ روز اخیر داده‌ای برای نمایش وجود ندارد.</div>}
   </section>
   <section className="contract-chart-card"><div className="contract-chart-head"><div><span>توزیع قراردادها</span><h3>بر اساس نوع قرارداد</h3></div><b>{categories.reduce((n,x)=>n+Number(x.count||0),0).toLocaleString('fa-IR')} قرارداد</b></div>
     {categories.length?<div className="contract-category-bars">{categories.map(x=>{const n=Number(x.count||0);return <div className="contract-category-row" key={x.category}><div className="contract-category-meta"><span>{categoryLabels[x.category]||x.category||'عمومی'}</span><b>{n.toLocaleString('fa-IR')}</b></div><div className="contract-bar"><i style={{width:`${Math.max(4,n/maxCat*100)}%`}}/></div></div>})}</div>:<div className="contract-chart-empty">هنوز قراردادی برای دسته‌بندی وجود ندارد.</div>}
   </section>
 </div>;
}

function ContractsPanel({items,report,contacts,users,onReload,onOpen}){
 const [selected,setSelected]=useState(null),[editing,setEditing]=useState(null),[busy,setBusy]=useState(false),[filter,setFilter]=useState('all'),[detail,setDetail]=useState(null),[notice,setNotice]=useState(null);
 const editorRef=useRef(null);
 useEffect(()=>{if(editing){requestAnimationFrame(()=>{const el=editorRef.current;el?.scrollIntoView({behavior:'smooth',block:'start'});window.scrollTo({top:Math.max(0,(el?.getBoundingClientRect().top||0)+window.scrollY-24),behavior:'smooth'});});}},[editing]);
 const showNotice=(message,type='error')=>{setNotice({message,type});window.clearTimeout(showNotice._timer);showNotice._timer=window.setTimeout(()=>setNotice(null),4200)};
 const errorText=e=>e?.response?.data?.message||e?.message||'عملیات قرارداد انجام نشد';
 const summary=report?.summary||{}; const statusText={draft:'پیش‌نویس',sent:'ارسال‌شده',viewed:'مشاهده‌شده',signed:'امضاشده توسط مشتری',active:'فعال و نهایی',rejected:'ردشده'};
 const categoryText={training:'آموزش',consulting:'مشاوره',design:'طراحی سایت',development:'توسعه نرم‌افزار',maintenance:'پشتیبانی و نگهداری',general:'عمومی'};
 const list=items.filter(x=>filter==='all'||x.status===filter);
 const save=async()=>{
   if(!editing?.title?.trim()){showNotice('عنوان قرارداد را وارد کنید.');return}
   if(!editing?.contactId){showNotice('برای ثبت قرارداد، ابتدا مشتری را انتخاب کنید.');return}
   if(!editing?.assigneeId){showNotice('برای ثبت قرارداد، ابتدا مسئول قرارداد را انتخاب کنید.');return}
   setBusy(true);
   try{if(editing.id)await updateAdminContract(editing.id,editing);else await createAdminContract(editing);setEditing(null);showNotice('قرارداد با موفقیت ذخیره شد.','success');await onReload()}
   catch(e){showNotice(errorText(e))}
   finally{setBusy(false)}
 };
 const open=async x=>{setSelected(x.id);try{const r=await getAdminContract(x.id);setDetail(r.data)}catch(e){showNotice(errorText(e))}};
 const download=async id=>{setBusy(true);try{const blob=await downloadAdminContract(id);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`قرارداد-${detail?.number||id}.html`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);showNotice('فایل قرارداد آماده شد.','success')}catch(e){showNotice(errorText(e))}finally{setBusy(false)}};
 const send=async id=>{setBusy(true);try{const r=await sendAdminContract(id);const raw=r.data?.signingToken;const url=raw?`${window.location.origin}/contract-sign/${raw}`:'';if(url)await navigator.clipboard?.writeText(url);showNotice(url?'لینک امضا ساخته شد و در صورت امکان کپی شد.':'لینک امضا ساخته شد.','success');await onReload()}catch(e){showNotice(errorText(e))}finally{setBusy(false)}};
 return <div className="contracts-center contracts51 contracts52-redesign"><div className="contracts-hero"><div><span className="section-kicker">قراردادهای الکترونیکی</span><h2>مرکز قرارداد و امضای دیجیتال</h2><p>قرارداد آموزش، مشاوره، طراحی سایت، توسعه و پشتیبانی را ایجاد کنید، برای مشتری بفرستید و روند امضا را ثبت و پیگیری کنید.</p></div><div className="section-back-actions"><button className="btn btn-outline" onClick={()=>onOpen?.('crm')}>← بازگشت به CRM</button><button className="btn btn-outline" onClick={()=>onOpen?.('dashboard')}>⌂ پیشخوان اصلی</button><button className="btn btn-primary" onClick={()=>{setEditing({title:'',category:'training',body:'',amount:0,currency:'تومان',contactId:'',signerName:'',signerEmail:'',signerPhone:'',expiresAt:'',assigneeId:''});setTimeout(()=>{const el=document.querySelector('.contract-form-modal');const main=el?.closest('.admin-main');if(el&&main)main.scrollTo({top:Math.max(0,el.offsetTop-28),behavior:'smooth'});else el?.scrollIntoView({behavior:'smooth',block:'start'});},80)}}>+ قرارداد جدید</button></div></div>
 <div className="contract-kpis"><div><span>کل قراردادها</span><b>{summary.total||0}</b></div><div><span>در انتظار امضا</span><b>{summary.waiting||0}</b></div><div><span>امضاشده</span><b>{summary.signed||0}</b></div><div><span>فعال و نهایی</span><b>{summary.active||0}</b></div><div><span>ارزش قراردادهای امضاشده</span><b>{Number(summary.total_value||0).toLocaleString('fa-IR')} <small>تومان</small></b></div></div>
 <div className="contract-status-tabs">{[['all','همه'],['draft','پیش‌نویس'],['sent','ارسال‌شده'],['viewed','مشاهده‌شده'],['signed','امضاشده'],['active','فعال'],['rejected','ردشده']].map(([k,v])=><button className={filter===k?'active':''} key={k} onClick={()=>setFilter(k)}>{v}</button>)}</div>
 <ContractCharts report={report}/>
 <div className="contract-layout"><section className="contract-list">{list.map(x=><button key={x.id} className={`contract-card ${selected===x.id?'selected':''}`} onClick={()=>open(x)}><div><span className="contract-number">قرارداد #{x.number}</span><h3>{x.title}</h3><p>{x.contact_name||x.signer_name||'بدون طرف قرارداد'}</p></div><div className="contract-card-foot"><span>{categoryText[x.category]||x.category}</span><span className="contract-assignee">👤 {x.assignee_name||x.assignee_username||"بدون مسئول"}</span><b className={`contract-status ${x.status}`}>{statusText[x.status]||x.status}</b></div></button>)}{!list.length&&<div className="empty-state">قراردادی در این وضعیت وجود ندارد.</div>}</section><section className="contract-detail">{detail?<><div className="contract-detail-head"><div><span className="contract-number">قرارداد #{detail.number}</span><h2>{detail.title}</h2><p>{detail.contact_name||detail.signer_name||'طرف قرارداد مشخص نشده'}</p></div><div className="contract-detail-head-right"><b className={`contract-status ${detail.status}`}>{statusText[detail.status]}</b><label className="contract-assign-control"><span>مسئول پرونده</span><select value={detail.assignee_id||""} onChange={async e=>{try{await assignAdminContract(detail.id,e.target.value||null);const r=await getAdminContract(detail.id);setDetail(r.data);await onReload()}catch(err){alert(err?.response?.data?.message||err.message||"ارجاع قرارداد ناموفق بود")}}}><option value="">بدون مسئول</option>{users.filter(u=>u.status!=='suspended').map(u=><option key={u.id} value={u.id}>{u.name||u.username} · {u.role}</option>)}</select></label></div></div><div className="contract-info-grid"><div><span>مبلغ</span><b>{Number(detail.amount||0).toLocaleString('fa-IR')} {detail.currency}</b></div><div><span>نوع</span><b>{categoryText[detail.category]||detail.category}</b></div><div><span>امضاکننده</span><b>{detail.signer_name||'—'}</b></div><div><span>ایمیل</span><b>{detail.signer_email||'—'}</b></div><div><span>مسئول پرونده</span><b>{detail.assignee_name||detail.assignee_username||'بدون مسئول'}</b></div></div><div className="contract-body-preview">{detail.body||'متن قرارداد ثبت نشده است.'}</div><div className="contract-actions"><button className="btn btn-outline" disabled={busy} onClick={()=>download(detail.id)}>دانلود قرارداد</button>{detail.status==='draft'&&<><button className="btn btn-outline" onClick={()=>setEditing({...detail,assigneeId:detail.assignee_id||'',contactId:detail.contact_id||'',signerName:detail.signer_name||'',signerEmail:detail.signer_email||'',signerPhone:detail.signer_phone||''})}>ویرایش</button><button className="btn btn-primary" disabled={busy} onClick={()=>send(detail.id)}>ایجاد لینک امضا</button></>}{detail.status==='signed'&&<button className="btn btn-primary" onClick={async()=>{await countersignAdminContract(detail.id);await onReload();open(detail)}}>تأیید نهایی قرارداد</button>}{['draft','sent','viewed'].includes(detail.status)&&<button className="btn btn-outline danger-btn" onClick={async()=>{const reason=prompt('دلیل رد یا لغو قرارداد؟')||'';await rejectAdminContract(detail.id,reason);await onReload();open(detail)}}>لغو قرارداد</button>}</div><div className="contract-events">{(detail.events||[]).map(e=><div key={e.id}><b>{e.event_type==='signed'?'امضا':e.event_type==='sent'?'ارسال':'رویداد قرارداد'}</b><span>{new Date(e.created_at).toLocaleString('fa-IR')}</span></div>)}</div></>:<div className="empty-state contract-empty">یک قرارداد را انتخاب کنید.</div>}</section></div>
 {notice&&<div className={`contract-toast ${notice.type}`} role="alert"><span>{notice.type==='success'?'✓':'!'}</span><div>{notice.message}</div><button type="button" onClick={()=>setNotice(null)}>×</button></div>}
 {editing&&<div className="inline-modal contract-form-modal"><div ref={editorRef} className="editor-modal contract-editor"><div className="panel-title"><h3>{editing.id?'ویرایش قرارداد':'قرارداد جدید'}</h3><button className="icon-btn" onClick={()=>setEditing(null)}>×</button></div><div className="editor-grid"><Field l="عنوان قرارداد" v={editing.title} s={v=>setEditing({...editing,title:v})}/><label className="field"><span>نوع قرارداد</span><select value={editing.category||'general'} onChange={e=>setEditing({...editing,category:e.target.value})}><option value="training">آموزش</option><option value="consulting">مشاوره</option><option value="design">طراحی سایت</option><option value="development">توسعه نرم‌افزار</option><option value="maintenance">پشتیبانی و نگهداری</option><option value="general">عمومی</option></select></label><label className="field"><span>طرف قرارداد <em className="required-mark">الزامی</em></span><select value={editing.contactId||''} onChange={e=>{const c=contacts.find(x=>x.id===e.target.value);setEditing({...editing,contactId:e.target.value,signerName:c?.name||editing.signerName,signerEmail:c?.email||editing.signerEmail,signerPhone:c?.phone||editing.signerPhone})}}><option value="">انتخاب مشتری</option>{contacts.map(c=><option key={c.id} value={c.id}>{c.name}{c.company?` · ${c.company}`:''}</option>)}</select></label><label className="field"><span>مسئول قرارداد / ارجاع به <em className="required-mark">الزامی</em></span><select value={editing.assigneeId||editing.assignee_id||""} onChange={e=>setEditing({...editing,assigneeId:e.target.value})}><option value="">بدون مسئول</option>{users.filter(u=>u.status!=='suspended').map(u=><option key={u.id} value={u.id}>{u.name||u.username} · {u.role}</option>)}</select></label><Field l="مبلغ" v={editing.amount} s={v=>setEditing({...editing,amount:v})}/><Field l="نام امضاکننده" v={editing.signerName} s={v=>setEditing({...editing,signerName:v})}/><Field l="ایمیل امضاکننده" v={editing.signerEmail} s={v=>setEditing({...editing,signerEmail:v})}/><Field l="تلفن امضاکننده" v={editing.signerPhone} s={v=>setEditing({...editing,signerPhone:v})}/></div><Field l="متن قرارداد" v={editing.body} s={v=>setEditing({...editing,body:v})} a/><p className="contract-note">پس از ارسال، برای طرف قرارداد یک لینک امن امضا ایجاد می‌شود. امضا با نام، زمان، IP، مرورگر و اثرانگشت رمزنگاری‌شده ثبت می‌شود.</p><button className="btn btn-primary full-btn" disabled={busy||!editing.title} onClick={save}>{busy?'در حال ذخیره...':'ذخیره پیش‌نویس'}</button></div></div>}
 </div>;
}

function TicketsPanel({items,categories,contacts,users,onReload,onOpen}){
 const [selected,setSelected]=useState(null),[detail,setDetail]=useState(null),[reply,setReply]=useState(''),[internal,setInternal]=useState(false),[busy,setBusy]=useState(false),[filter,setFilter]=useState('all'),[showForm,setShowForm]=useState(false),[showCats,setShowCats]=useState(false),[editingCat,setEditingCat]=useState(null);
 const empty={subject:'',description:'',categoryId:categories.find(x=>x.active!==false)?.id||'',category:'',priority:'normal',status:'open',contactId:'',userId:'',assigneeId:'',team:'',slaDueAt:''};
 const [form,setForm]=useState(empty);
 const list=items.filter(t=>filter==='all'||t.status===filter);
 const open=async t=>{setSelected(t.id);try{const r=await getAdminTicket(t.id);setDetail(r.data)}catch(e){alert(e?.response?.data?.message||e.message)}};
 const send=async()=>{if(!reply.trim())return;setBusy(true);try{if(internal)await internalReplyAdminTicket(selected,{body:reply});else await replyAdminTicket(selected,{body:reply});setReply('');const r=await getAdminTicket(selected);setDetail(r.data);await onReload()}finally{setBusy(false)}};
 const create=()=>{setForm({...empty,categoryId:categories.find(x=>x.active!==false)?.id||''});setShowForm(true);requestAnimationFrame(()=>document.querySelector('.ticket-create-form')?.scrollIntoView({behavior:'smooth',block:'start'}))};
 const save=async()=>{if(!form.subject.trim()||!form.categoryId){alert('موضوع و دسته‌بندی تیکت الزامی است.');return}setBusy(true);try{const cat=categories.find(x=>x.id===form.categoryId);await createAdminTicket({...form,category:cat?.name||''});setShowForm(false);setForm(empty);await onReload()}catch(e){alert(e?.response?.data?.message||e.message||'ثبت تیکت ناموفق بود')}finally{setBusy(false)}};
 const saveCat=async()=>{if(!editingCat?.name?.trim())return;setBusy(true);try{if(editingCat.id)await updateAdminTicketCategory(editingCat.id,editingCat);else await createAdminTicketCategory(editingCat);setEditingCat(null);await onReload()}catch(e){alert(e?.response?.data?.message||e.message||'ذخیره دسته‌بندی ناموفق بود')}finally{setBusy(false)}};
 return <div className="admin-panel ticket-panel ticket-pro-panel"><div className="panel-title"><div><h2>مرکز تیکت و پشتیبانی</h2><p className="muted">ثبت حرفه‌ای تیکت، دسته‌بندی، اولویت، SLA، تخصیص کارشناس و پاسخ عمومی/داخلی.</p></div><div className="section-back-actions"><button className="btn btn-outline" onClick={()=>onOpen?.("crm")}>← بازگشت به CRM</button><button className="btn btn-outline" onClick={()=>onOpen?.("dashboard")}>⌂ پیشخوان اصلی</button><button className="btn btn-outline" onClick={()=>setShowCats(v=>!v)}>⚙ مدیریت دسته‌بندی‌ها</button><button className="btn btn-primary" onClick={create}>+ تیکت جدید</button></div></div>
 {showCats&&<div className="ticket-category-manager"><div className="ticket-category-head"><div><h3>دسته‌بندی‌های تیکت</h3><p>دسته‌بندی‌های فعال در فرم ثبت تیکت از اینجا مدیریت می‌شوند.</p></div><button className="btn btn-primary" onClick={()=>setEditingCat({name:'',description:'',color:'#2587ff',sortOrder:0,active:true})}>+ دسته‌بندی جدید</button></div><div className="ticket-category-grid">{categories.map(c=><div className="ticket-category-card" key={c.id}><span className="ticket-category-dot" style={{background:c.color}}/><div><b>{c.name}</b><small>{c.description||'بدون توضیح'}</small></div><em>{c.active?'فعال':'غیرفعال'}</em><div className="row-actions"><button className="btn btn-outline" onClick={()=>setEditingCat({...c,sortOrder:c.sort_order})}>ویرایش</button><button className="btn btn-outline danger-btn" onClick={async()=>{if(confirm('این دسته‌بندی حذف شود؟')){try{await deleteAdminTicketCategory(c.id);await onReload()}catch(e){alert(e?.response?.data?.message||e.message)}}}}>حذف</button></div></div>)}</div>{editingCat&&<div className="ticket-category-editor"><Field l="نام دسته‌بندی" v={editingCat.name} s={v=>setEditingCat({...editingCat,name:v})}/><Field l="توضیح" v={editingCat.description} s={v=>setEditingCat({...editingCat,description:v})}/><label className="field"><span>رنگ</span><input type="color" value={editingCat.color||'#2587ff'} onChange={e=>setEditingCat({...editingCat,color:e.target.value})}/></label><Field l="ترتیب نمایش" v={editingCat.sortOrder} s={v=>setEditingCat({...editingCat,sortOrder:v})}/><label className="check-field"><input type="checkbox" checked={editingCat.active!==false} onChange={e=>setEditingCat({...editingCat,active:e.target.checked})}/> فعال باشد</label><div className="row-actions"><button className="btn btn-primary" onClick={saveCat} disabled={busy}>ذخیره دسته‌بندی</button><button className="btn btn-outline" onClick={()=>setEditingCat(null)}>انصراف</button></div></div>}</div>}
 {showForm&&<div className="ticket-create-form"><div className="ticket-form-head"><div><span className="eyebrow">فرم ثبت تیکت</span><h3>ایجاد درخواست پشتیبانی جدید</h3></div><button className="icon-btn" onClick={()=>setShowForm(false)}>×</button></div><div className="ticket-form-grid"><Field l="موضوع تیکت" v={form.subject} s={v=>setForm({...form,subject:v})}/><label className="field"><span>دسته‌بندی <em className="required-mark">الزامی</em></span><select value={form.categoryId} onChange={e=>setForm({...form,categoryId:e.target.value})}><option value="">انتخاب دسته‌بندی</option>{categories.filter(x=>x.active!==false).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="field"><span>مشتری</span><select value={form.contactId} onChange={e=>{const c=contacts.find(x=>x.id===e.target.value);setForm({...form,contactId:e.target.value,userId:c?.user_id||''})}}><option value="">بدون مشتری</option>{contacts.map(c=><option key={c.id} value={c.id}>{c.name}{c.company?` · ${c.company}`:''}</option>)}</select></label><label className="field"><span>حساب کاربری مشتری</span><select value={form.userId} onChange={e=>setForm({...form,userId:e.target.value})}><option value="">بدون حساب</option>{users.filter(u=>u.status!=='suspended').map(u=><option key={u.id} value={u.id}>{u.name||u.username} · {u.username}</option>)}</select></label><label className="field"><span>اولویت</span><select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option value="low">کم</option><option value="normal">عادی</option><option value="high">بالا</option><option value="urgent">فوری</option></select></label><label className="field"><span>مسئول / کارشناس</span><select value={form.assigneeId} onChange={e=>setForm({...form,assigneeId:e.target.value})}><option value="">بدون مسئول</option>{users.filter(u=>u.status!=='suspended').map(u=><option key={u.id} value={u.id}>{u.name||u.username} · {u.role}</option>)}</select></label><Field l="تیم" v={form.team} s={v=>setForm({...form,team:v})}/><Field l="مهلت SLA" v={form.slaDueAt} s={v=>setForm({...form,slaDueAt:v})}/></div><label className="field ticket-description-field"><span>شرح کامل درخواست</span><textarea rows="7" value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="شرح مشکل، درخواست، اطلاعات تکمیلی و هر چیزی که کارشناس باید بداند..."/></label><div className="ticket-form-footer"><span>پس از ثبت، تیکت در فهرست قرار می‌گیرد و قابل تخصیص و پاسخ‌گویی است.</span><button className="btn btn-primary" disabled={busy} onClick={save}>{busy?'در حال ثبت...':'ثبت تیکت'}</button></div></div>}
 <div className="ticket-layout"><div><div className="ticket-filters">{[['all','همه'],['open','باز'],['in_progress','درحال بررسی'],['pending','منتظر پاسخ'],['resolved','حل‌شده'],['closed','بسته']].map(([k,v])=><button key={k} className={filter===k?'active':''} onClick={()=>setFilter(k)}>{v}</button>)}</div>{list.map(t=><button className={`ticket-row ${selected===t.id?'selected':''}`} key={t.id} onClick={()=>open(t)}><div><b>#{t.number} · {t.subject}</b><span>{t.category_name||t.category||'بدون دسته'} · {t.contact_name||'بدون مشتری'} · {t.assignee_username||'بدون کارشناس'}</span></div><em className={`priority ${t.priority}`}>{t.priority}</em><strong>{t.status}</strong></button>)}{!list.length&&<div className="empty-state">تیکتی وجود ندارد.</div>}</div>{detail?<div className="ticket-detail"><div className="ticket-detail-head"><div><h3>#{detail.number} · {detail.subject}</h3><span>{detail.category_name||detail.category||'بدون دسته'} · {detail.contact_name||'بدون مشتری'}</span></div><div className="ticket-detail-controls"><label><span>دسته‌بندی</span><select value={detail.category_id||''} onChange={async e=>{const cat=categories.find(c=>c.id===e.target.value);await updateAdminTicket(detail.id,{...detail,categoryId:e.target.value,category:cat?.name||'',assigneeId:detail.assignee_id||null});const r=await getAdminTicket(detail.id);setDetail(r.data);await onReload()}}>{categories.filter(c=>c.active||c.id===detail.category_id).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label><span>وضعیت</span><select value={detail.status} onChange={async e=>{await updateAdminTicket(detail.id,{...detail,status:e.target.value,categoryId:detail.category_id,category:detail.category,assigneeId:detail.assignee_id||null});const r=await getAdminTicket(detail.id);setDetail(r.data);await onReload()}}><option value="open">باز</option><option value="in_progress">در حال بررسی</option><option value="pending">منتظر پاسخ</option><option value="resolved">حل‌شده</option><option value="closed">بسته</option></select></label><label><span>ارجاع به</span><select value={detail.assignee_id||""} onChange={async e=>{await updateAdminTicket(detail.id,{subject:detail.subject,categoryId:detail.category_id,category:detail.category,priority:detail.priority,status:detail.status,assigneeId:e.target.value||null,team:detail.team||"",slaDueAt:detail.sla_due_at||null});const r=await getAdminTicket(detail.id);setDetail(r.data);await onReload()}}><option value="">بدون مسئول</option>{users.filter(u=>u.status!=='suspended').map(u=><option key={u.id} value={u.id}>{u.name||u.username} · {u.role}</option>)}</select></label></div></div><div className="ticket-messages">{(detail.messages||[]).map(m=><div className={`ticket-message ${m.is_internal?'internal':''}`} key={m.id}><b>{m.is_internal?'🔒 یادداشت داخلی':'💬 پاسخ عمومی'} · {m.author||'مدیر'}</b><p>{m.body}</p><small>{new Date(m.created_at).toLocaleString('fa-IR')}</small></div>)}</div><div className="ticket-reply"><div className="check-field"><label><input type="checkbox" checked={internal} onChange={e=>setInternal(e.target.checked)}/> پاسخ داخلی تیم</label></div><textarea rows="5" value={reply} onChange={e=>setReply(e.target.value)} placeholder={internal?'یادداشت داخلی...':'پاسخ برای مشتری...'}/><button className="btn btn-primary" disabled={busy} onClick={send}>{busy?'در حال ارسال...':internal?'ثبت یادداشت داخلی':'ارسال پاسخ'}</button></div></div>:<div className="empty-state">یک تیکت را انتخاب کنید.</div>}</div></div>
}

function MediaPanel({value,onReload,loadError}){
  const [uploading,setUploading]=useState(false),[uploadProgress,setUploadProgress]=useState(0),[action,setAction]=useState('');
  const jobs=value?.jobs||[],lessons=value?.lessons||[];
  const statusLabel={queued:'در صف',processing:'در حال تبدیل',ready:'آماده',failed:'خطا'};
  const formatDuration=(seconds)=>{const n=Number(seconds);if(!Number.isFinite(n)||n<=0)return '—';const s=Math.round(n),h=Math.floor(s/3600),m=Math.floor((s%3600)/60),ss=s%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(ss).padStart(2,'0')}`:`${m}:${String(ss).padStart(2,'0')}`};
  const upload=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;setUploading(true);setUploadProgress(0);try{await uploadVideo(file,p=>setUploadProgress(p));await onReload()}catch(err){alert(err?.response?.data?.message||err?.message||'آپلود ویدئو ناموفق بود')}finally{setUploading(false)}};
  const retry=async id=>{setAction(id);try{await retryAdminMedia(id);await onReload()}catch(err){alert(err?.response?.data?.message||err?.message||'Retry ناموفق بود')}finally{setAction('')}};
  const attach=async(jobId,lessonId)=>{if(!lessonId)return;setAction(`${jobId}:attach`);try{await attachAdminMedia(jobId,lessonId);await onReload()}catch(err){alert(err?.response?.data?.message||err?.message||'اتصال ویدئو به درس ناموفق بود')}finally{setAction('')}};
  const remove=async id=>{if(!confirm('این ویدئو و خروجی‌های HLS آن حذف شوند؟ اگر به درسی متصل باشد اتصال درس هم پاک می‌شود.'))return;setAction(id);try{await deleteAdminMedia(id);await onReload()}catch(err){alert(err?.response?.data?.message||err?.message||'حذف ویدئو ناموفق بود')}finally{setAction('')}};
  useEffect(()=>{if(!jobs.some(x=>['queued','processing'].includes(x.status)))return;const t=setInterval(onReload,3000);return()=>clearInterval(t)},[jobs.map(x=>`${x.id}:${x.status}:${x.progress}`).join('|')]);
  return <div className="admin-panel media-admin-panel">
    {loadError&&<div className="form-msg show err"><b>خطا در دریافت Media:</b> {loadError}<button className="btn btn-outline" style={{marginRight:12}} onClick={onReload}>تلاش دوباره</button></div>}
    <div className="panel-title"><div><h2>مدیریت ویدئو و تبدیل HLS</h2><p className="muted">وضعیت Worker ویدئوها از PostgreSQL خوانده می‌شود؛ مدیر می‌تواند Retry، حذف و اتصال به درس را کنترل کند.</p></div><label className="btn btn-primary media-upload-btn">{uploading?`آپلود ${uploadProgress}%`:'+ افزودن ویدئو'}<input type="file" accept="video/*" onChange={upload} disabled={uploading}/></label></div>
    {uploading&&<div className="media-progress"><div style={{width:`${uploadProgress}%`}}/><span>{uploadProgress}%</span></div>}
    {!jobs.length&&<div className="empty-state">هنوز ویدئویی در Media ثبت نشده است.</div>}
    <div className="media-job-list">{jobs.map(j=>{
      const linked=j.lesson;
      return <article className="media-job-card" key={j.id}>
        <div className="media-job-head"><div><b>{j.original_name||j.filename}</b><span>{j.id}</span></div><span className={`media-status ${j.status}`}>{statusLabel[j.status]||j.status}</span></div>
        <div className="media-meta-grid"><div><small>پیشرفت</small><strong>{Number(j.progress||0)}%</strong></div><div><small>مدت</small><strong>{formatDuration(j.duration_seconds??j.durationSeconds)}</strong></div><div><small>تلاش</small><strong>{j.attempts||0} / {j.max_attempts||3}</strong></div><div><small>کیفیت جاری</small><strong>{j.quality||'—'}</strong></div></div>
        {(j.status==='queued'||j.status==='processing')&&<div className="media-progress"><div style={{width:`${Number(j.progress||0)}%`}}/><span>{Number(j.progress||0)}%</span></div>}
        {j.error&&<div className="media-error"><b>خطای FFmpeg</b><pre>{j.error}</pre></div>}
        <div className="media-attach"><label className="field"><span>اتصال به درس</span><select value={linked?.id||''} onChange={e=>attach(j.id,e.target.value)} disabled={action===`${j.id}:attach`}><option value="">{linked?'اتصال فعلی: '+linked.title:'یک درس انتخاب کنید'}</option>{lessons.map(l=><option key={l.id} value={l.id}>{l.courseTitle} — {l.title}</option>)}</select></label>{linked&&<div className="badge">متصل: {linked.courseTitle} / {linked.title}</div>}</div>
        {j.status==='ready'&&<MediaPreview mediaId={j.id}/>}<div className="row-actions media-actions">{j.status==='failed'&&<button className="btn btn-outline" disabled={action===j.id} onClick={()=>retry(j.id)}>{action===j.id?'در حال Retry...':'↻ Retry'}</button>} {j.status==='ready'&&<span className="badge success">HLS آماده است</span>}<button className="btn btn-outline danger-btn" disabled={action===j.id} onClick={()=>remove(j.id)}>حذف ویدئو</button></div>
      </article>})}</div>
  </div>
}
